package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

// ============ platform/response：统一响应体 ============

// Envelope 是所有接口共用的响应外壳。对应 tech-plan §6.2。
// data 用 any（而不是 map[string]any）：既能装 map，也能装 struct。
type Envelope struct {
	Code      int    `json:"code"`
	Message   string `json:"message"`
	Data      any    `json:"data"`
	RequestID string `json:"request_id"`
}

// HealthData 是 /healthz 的 data 部分。
type HealthData struct {
	Service string `json:"service"`
	Status  string `json:"status"`
}

// OK 是唯一允许被 handler 调用的「写成功响应」函数。
// 把 c.JSON 收进这个函数，是为了不让任何 handler 手写外壳——
// 手写就意味着迟早有一天有人漏掉 request_id。
func OK(c *gin.Context, data any) {
	c.JSON(http.StatusOK, Envelope{
		Code:      0,
		Message:   "ok",
		Data:      data,
		RequestID: c.GetString("request_id"),
	})
}

// ============ handler：只做「解析 → 调service → 组装响应」============

func healthz(c *gin.Context) {
	// 真实项目里这里会调 service.Check(c.Request.Context())
	OK(c, HealthData{Service: "svc-homeos", Status: "up"})
}

// ping 演示「分组内的一个最小业务接口」
func ping(c *gin.Context) {
	OK(c, gin.H{"pong": "homeos"})
}

// ============ 路由装配 ============

func BuildRouter() *gin.Engine {
	// gin.DefaultMode 会在启动时打印一堆调试信息，输出不干净；
	// ReleaseMode 只在真正的生产进程里用。
	gin.SetMode(gin.ReleaseMode)

	r := gin.New()

	// 1) 根路径只放运维接口（探活）。业务接口一律不许放根路径。
	r.GET("/healthz", healthz)

	// 2) 业务接口必须挂在 /api/{code}/ 下，这是七类命名同源里的一类。
	//    分组不是「路径字符串拼接」，它是 gin.RouterGroup 对象，
	//    挂着中间件也挂在分组上，所以下面的接口自动获得同样的待遇。
	api := r.Group("/api/homeos")
	{
		api.GET("/ping", ping)
	}

	return r
}

// ============ 用 httptest 起一个真服务器，避免占用固定端口 ============

func get(url string) (int, string) {
	resp, err := http.Get(url)
	if err != nil {
		return 0, fmt.Sprintf("请求失败: %v", err)
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return resp.StatusCode, string(b)
}

func main() {
	r := BuildRouter()

	// httptest.NewServer 起的是**真的 net/http 服务器**（随机端口），
	// 但不需要你手动挑端口、也不会和别的进程撞。
	// 这跟 d5 要学的 httptest.NewRecorder（不起 socket，只测 handler）是两件事。
	ts := httptest.NewServer(r)
	defer ts.Close()

	fmt.Println("=== 1. 路由表（r.Routes() 打印 gin 真实注册了什么）===")
	for _, rt := range r.Routes() {
		fmt.Printf("  %-6s %s\n", rt.Method, rt.Path)
	}

	fmt.Println("\n=== 2. GET /healthz ===")
	code, body := get(ts.URL + "/healthz")
	fmt.Printf("  HTTP %d\n", code)
	fmt.Printf("  body: %s\n", body)

	fmt.Println("\n=== 3. GET /api/homeos/ping ===")
	code, body = get(ts.URL + "/api/homeos/ping")
	fmt.Printf("  HTTP %d\n", code)
	fmt.Printf("  body: %s\n", body)

	fmt.Println("\n=== 4. 请求日志中间件把 request_id 注入上下文 ===")
	// 现在中间件还没写，所以request_id 是空串。d3 会补上。
	var env Envelope
	_ = json.Unmarshal([]byte(body), &env)
	fmt.Printf("  解析出的 request_id = %q ← d3 之前是空的\n", env.RequestID)

	fmt.Println("\n=== 5. 没注册的路径 gin 默认返回 404（不是我们的响应体）===")
	code, body = get(ts.URL + "/api/finance/categories")
	fmt.Printf("  HTTP %d\n", code)
	fmt.Printf("  body: %s\n", body)
	fmt.Println("  注意：这body 是 gin 的默认文本响应，不是 Envelope ——")
	fmt.Println("  说明还有路径没被我们的统一响应体接管，d2 会用 NoRoute 补上。")

	fmt.Println("\n=== S2 d1 到此结束 ===")
	fmt.Println("下一步（d2）：把 POST /api/homeos/echo 做出来，并解决上面第 5 条的 404 形状不一致。")
}

package main

import (
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/gin-gonic/gin/binding"
	"github.com/go-playground/validator/v10"
)

// ============ platform/response：统一响应体 ============

type Envelope struct {
	Code      int          `json:"code"`
	Message   string       `json:"message"`
	Data      any          `json:"data"`
	RequestID string       `json:"request_id"`
	Errors    []FieldError `json:"errors,omitempty"`
}

// FieldError 承载字段级校验错误（对应 S1 d16 的 ValidationError）。
type FieldError struct {
	Field  string `json:"field"`
	Reason string `json:"reason"`
}

func OK(c *gin.Context, data any) {
	c.JSON(http.StatusOK, Envelope{Code: 0, Message: "ok", Data: data, RequestID: c.GetString("request_id")})
}

// Fail 把 HTTP 状态码 + 业务码 + 响应体一次写全。
func Fail(c *gin.Context, status, code int, msg string, errs []FieldError) {
	c.JSON(status, Envelope{Code: code, Message: msg, Data: nil, RequestID: c.GetString("request_id"), Errors: errs})
}

// ============ DTO：请求 / 响应两个不同的 struct ============

type EchoRequest struct {
	Name  string   `json:"name"  binding:"required,min=1,max=20"`
	Age   int      `json:"age"   binding:"required,min=0,max=150"`
	Email string   `json:"email" binding:"omitempty,email"`
	Tags  []string `json:"tags"  binding:"max=3,dive,max=8"`
}

// EchoResponse 刻意不复用 EchoRequest：请求要 binding 标签，
// 响应不能有；字段也不同（Email 变成 has_email 布尔）。
type EchoResponse struct {
	Name     string   `json:"name"`
	Age      int      `json:"age"`
	HasEmail bool     `json:"has_email"`
	Tags     []string `json:"tags"`
	Accepted bool     `json:"accepted"`
}

// ============ handler ============

func echo(c *gin.Context) {
	var req EchoRequest

	// 关键：ShouldBindJSON 把「JSON 语法错」和「binding 规则不满足」
	// 用同一个 error 返回。不区分的话，前端会把所有 4xx 都当成
	// 「你发的东西我读不懂」，重试一万次也没用。
	if err := c.ShouldBindJSON(&req); err != nil {
		var ve validator.ValidationErrors
		if errors.As(err, &ve) {
			// 分支 A：是字段规则不满足 → 422 +逐字段原因
			Fail(c, http.StatusUnprocessableEntity, 1002, "参数校验失败", flatten(ve))
			return
		}
		// 分支 B：是 JSON 根本解析不了 → 400，不带字段列表
		Fail(c, http.StatusBadRequest, 1001, "请求体不是合法 JSON", nil)
		return
	}

	// binding 表达不了的业务规则放这里。errors 显式给空切片，
	// 因为 Go 的 nil slice 会被 json 序列化成 null，前端期望[]。
	fieldErrs := []FieldError{}
	if strings.TrimSpace(req.Name) == "" {
		fieldErrs = append(fieldErrs, FieldError{Field: "name", Reason: "不能全是空格"})
	}
	if len(fieldErrs) > 0 {
		Fail(c, http.StatusUnprocessableEntity, 1002, "参数校验失败", fieldErrs)
		return
	}

	OK(c, EchoResponse{
		Name:     req.Name,
		Age:      req.Age,
		HasEmail: req.Email != "",
		Tags:     orEmpty(req.Tags),
		Accepted: true,
	})
}

func orEmpty(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}

// flatten 把 validator.ValidationErrors 翻译成前端能用的字段列表。
// 注意不能直接用 fe.Error()：它会把 Go 的类型名和 tag 名一起吐给用户
// （"Key: 'EchoRequest.Age' Error:Field validation for 'Age' failed on the 'max' tag"），
// 那是内部实现细节，改个 struct 名就变了。必须自己映射成稳定文案。
func flatten(ve validator.ValidationErrors) []FieldError {
	out := make([]FieldError, 0, len(ve))
	for _, fe := range ve {
		out = append(out, FieldError{Field: jsonFieldName(fe), Reason: tagReason(fe)})
	}
	return out
}

// tagReason 把 validator 的 tag 翻成中文文案。
func tagReason(fe validator.FieldError) string {
	switch fe.Tag() {
	case "required":
		return "必填"
	case "min":
		return "最小值是 " + fe.Param()
	case "max":
		return "最大值是 " + fe.Param()
	case "email":
		return "不是合法邮箱"
	}
	return "不满足 " + fe.Tag() + " 规则"
}

// jsonFieldName 把 validator 的 Go 字段名（Name）换成 JSON 名（name）。
func jsonFieldName(fe validator.FieldError) string {
	switch fe.Field() {
	case "Name":
		return "name"
	case "Age":
		return "age"
	case "Email":
		return "email"
	case "Tags":
		return "tags"
	}
	return fe.Field()
}

// ============ 路由 ============

func BuildRouter() *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.GET("/healthz", func(c *gin.Context) {
		OK(c, gin.H{"service": "svc-homeos", "status": "up"})
	})
	api := r.Group("/api/homeos")
	api.POST("/echo", echo)
	// 补上 d1 留下的坑：未注册路径也走统一响应体
	r.NoRoute(func(c *gin.Context) {
		Fail(c, http.StatusNotFound, 3001, "接口不存在", nil)
	})
	return r
}

// 让 validator 用我们自己的 tag（默认就是 "binding"，写出来是为了看得见）
var _ = binding.Validator

func do(ts *httptest.Server, method, path, body string) (int, string) {
	var rdr io.Reader
	if body != "" {
		rdr = strings.NewReader(body)
	}
	req, err := http.NewRequest(method, ts.URL+path, rdr)
	if err != nil {
		return 0, err.Error()
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return 0, err.Error()
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return resp.StatusCode, string(b)
}

func main() {
	ts := httptest.NewServer(BuildRouter())
	defer ts.Close()

	cases := []struct {
		title string
		body  string
	}{
		{"合法请求", `{"name":"小林","age":30,"email":"lin@example.com","tags":["读书"]}`},
		{"name 缺失 → binding required（422）", `{"age":30}`},
		{"age 越界 + email 非法 → 两个字段同时报错", `{"name":"小林","age":999,"email":"not-an-email"}`},
		{"tags 超过 3 个 → dive 生效", `{"name":"小林","age":20,"tags":["a","b","c","d"]}`},
		{"JSON 语法错（多一个逗号）→ 400", `{"name":"小林","age":20,}`},
		{"字段类型错（age 传了字符串）→ 400", `{"name":"小林","age":"三十"}`},
		{"name 全是空格 → binding 放行，业务规则拦下", `{"name":"   ","age":20}`},
		{"无 tags → null 被换成 []", `{"name":"小森","age":18}`},
	}

	for i, c := range cases {
		fmt.Printf("=== %d. %s ===\n", i+1, c.title)
		fmt.Printf("  请求: %s\n", c.body)
		code, body := do(ts, http.MethodPost, "/api/homeos/echo", c.body)
		fmt.Printf("  HTTP %d\n  body: %s\n\n", code, body)
	}

	fmt.Println("=== 9. d1 的遗留问题已修：未注册路径也是统一响应体 ===")
	code, body := do(ts, http.MethodGet, "/api/finance/categories", "")
	fmt.Printf("  HTTP %d\n  body: %s\n", code, body)

	fmt.Println("\n=== S2 d2 到此结束 ===")
	fmt.Println("下一步（d3）：上面 8 次调用在日志里长得一模一样，加request_id 才查得动。")
}

