package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
	"net/http/httptest"
	"runtime/debug"
	"strings"
	"time"

	"github.com/gin-gonic/gin"
)

// ============ platform/response ============

type Envelope struct {
	Code      int    `json:"code"`
	Message   string `json:"message"`
	Data      any    `json:"data"`
	RequestID string `json:"request_id"`
}

func OK(c *gin.Context, data any) {
	c.JSON(http.StatusOK, Envelope{Code: 0, Message: "ok", Data: data, RequestID: c.GetString("request_id")})
}

func Fail(c *gin.Context, status, code int, msg string) {
	c.JSON(status, Envelope{Code: code, Message: msg, Data: nil, RequestID: c.GetString("request_id")})
}

// ============ platform/logger：极简结构化日志 ============
// 真实项目用 log/slog（Go 1.21+ 标准库），这里手写一个让你看清字段。
type Field struct {
	K string
	V any
}

type Entry struct {
	Msg    string
	Fields []Field
}

type Logger struct {
	out  func(Entry)
	name string
}

func NewLogger(name string, out func(Entry)) *Logger { return &Logger{out: out, name: name} }

func (l *Logger) Info(msg string, fields ...Field) {
	l.out(Entry{Msg: msg, Fields: append([]Field{{K: "service", V: l.name}}, fields...)})
}

// render 把Entry 渲染成一行 key=value，便于肉眼对齐。
func render(e Entry) string {
	var b strings.Builder
	b.WriteString(e.Msg)
	for _, f := range e.Fields {
		b.WriteString(" " + f.K + "=" + fmt.Sprintf("%v", f.V))
	}
	return b.String()
}

// ============ 中间件1：request id ============

const ctxRequestID = "request_id"

var seq int // 确定性 id 生成器（真实项目用 uuid）

// RequestID：优先用客户端传来的 X-Request-Id（前端重试时保持同一个 id），
// 没有就自己造。**必须**写回响应头，前端报错时截图就能带上门。
func RequestID() gin.HandlerFunc {
	return func(c *gin.Context) {
		rid := c.GetHeader("X-Request-Id")
		if rid == "" {
			seq++
			rid = fmt.Sprintf("req-%03d", seq)
		}
		c.Set(ctxRequestID, rid)
		c.Header("X-Request-Id", rid)
		c.Next() // 交棒给下一个中间件/handler
	}
}

// ============ 中间件2：请求日志 ============

func AccessLog(l *Logger) gin.HandlerFunc {
	return func(c *gin.Context) {
		start := time.Now()
		c.Next() // 关键：c.Next() 之后的代码在 handler 返回后才执行

		// 这里能读到 status，是因为 gin 的 ResponseWriter 在 Next 返回时已写完。
		l.Info("http",
			Field{"request_id", c.GetString(ctxRequestID)},
			Field{"method", c.Request.Method},
			Field{"path", c.Request.URL.Path},
			Field{"status", c.Writer.Status()},
			Field{"cost_ms", time.Since(start).Milliseconds()},
		)
	}
}

// ============ 中间件3：panic recovery ============
// gin 自带 gin.Recovery()，但它返回的是**纯文本** 500，
// 破坏统一响应体。自己写一个能同时：
//  1. recover住 panic，让进程不死
//  2. 写堆栈到日志（不返回给客户端）
//  3. 返回标准响应体
func Recovery(l *Logger) gin.HandlerFunc {
	return func(c *gin.Context) {
		defer func() {
			if r := recover(); r != nil {
				// debug.Stack() 必须在 recover 之后立刻调，否则栈已经展开
				l.Info("panic",
					Field{"request_id", c.GetString(ctxRequestID)},
					Field{"path", c.Request.URL.Path},
					Field{"panic", fmt.Sprintf("%v", r)},
					Field{"stack", string(debug.Stack())},
				)
				// 注意：AbortWithStatusJSON 会写响应并中断后续中间件。
				// 如果已经写过响应头（比如 handler 写了半个 JSON 再 panic），
				// 这里再写会导致「响应头已发送」警告，body 会拼成两段。
				c.AbortWithStatusJSON(http.StatusInternalServerError, Envelope{
					Code:      5000,
					Message:   "服务端错误",
					Data:      nil,
					RequestID: c.GetString(ctxRequestID),
				})
			}
		}()
		c.Next()
	}
}

// ============ handler ============

func healthz(c *gin.Context) {
	OK(c, gin.H{"service": "svc-homeos", "status": "up"})
}

func echo(c *gin.Context) {
	OK(c, gin.H{"said": c.PostForm("say") + "|rid=" + c.GetString(ctxRequestID)})
}

// boom 故意 panic，验证 recovery
func boom(c *gin.Context) {
	panic("数据库连接池炸了")
}

// boomAfterWrite：先写一半再 panic，演示「已写响应头后再写 body」的坑
func boomAfterWrite(c *gin.Context) {
	c.Header("Content-Type", "application/json")
	c.Status(http.StatusOK)
	_, _ = c.Writer.WriteString(`{"code":0,"data":{"partial"`)
	panic("写到一半崩了")
}

// ============ 装配 ============

func BuildRouter(l *Logger) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()

	// 顺序有讲究：RequestID 最先（后面所有中间件都要用它），
	// 然后 Recovery（要能兜住后面所有中间件的 panic），最后 AccessLog。
	r.Use(RequestID(), Recovery(l), AccessLog(l))

	r.GET("/healthz", healthz)
	api := r.Group("/api/homeos")
	api.POST("/echo", echo)
	api.GET("/boom", boom)
	api.GET("/boom-after-write", boomAfterWrite)

	r.NoRoute(func(c *gin.Context) {
		Fail(c, http.StatusNotFound, 3001, "接口不存在")
	})
	return r
}

func postForm(ts *httptest.Server, path, form string) string {
	resp, err := http.PostForm(ts.URL+path, urlValues(form))
	if err != nil {
		return "ERR: " + err.Error()
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return fmt.Sprintf("HTTP %d  x-request-id=%s\nbody: %s", resp.StatusCode, resp.Header.Get("X-Request-Id"), b)
}

func urlValues(form string) map[string][]string {
	m := map[string][]string{}
	for _, kv := range strings.Split(form, "&") {
		p := strings.SplitN(kv, "=", 2)
		if len(p) == 2 {
			m[p[0]] = []string{p[1]}
		}
	}
	return m
}

func main() {
	var logs []string
	l := NewLogger("svc-homeos", func(e Entry) { logs = append(logs, render(e)) })

	ts := httptest.NewServer(BuildRouter(l))
	defer ts.Close()

	run := func(title string, fn func()) {
		before := len(logs)
		fmt.Printf("=== %s ===\n", title)
		fn()
		fmt.Println("  --- 日志 ---")
		for _, line := range logs[before:] {
			// panic 日志带完整堆栈（几十行），打到 stdout 会淹没输出，
			// 真实项目里堆栈进文件、stdout 只留一行摘要。
			if i := strings.Index(line, "stack="); i >= 0 {
				fmt.Println("    " + line[:i] + "stack=<已省略，真实项目写进日志文件>")
				continue
			}
			fmt.Println("    " + line)
		}
		fmt.Println()
	}

	run("1. 正常请求：服务端生成 request_id 并写回响应头", func() {
		fmt.Println("  " + strings.ReplaceAll(postForm(ts, "/api/homeos/echo", "say=hi"), "\n", "\n  "))
	})

	run("2. 客户端自带 X-Request-Id → 服务端沿用（前端重试保持同一个 id）", func() {
		req, _ := http.NewRequest(http.MethodPost, ts.URL+"/api/homeos/echo", strings.NewReader("say=retry"))
		req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
		req.Header.Set("X-Request-Id", "req-from-frontend")
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			fmt.Println("  ERR:", err)
			return
		}
		defer resp.Body.Close()
		b, _ := io.ReadAll(resp.Body)
		fmt.Printf("  响应头 X-Request-Id = %s\n  body: %s\n", resp.Header.Get("X-Request-Id"), b)
	})

	run("3. handler panic → 被Recovery 兜住，仍是统一响应体", func() {
		resp, err := http.Get(ts.URL + "/api/homeos/boom")
		if err != nil {
			fmt.Println("  ERR:", err)
			return
		}
		defer resp.Body.Close()
		b, _ := io.ReadAll(resp.Body)
		fmt.Printf("  HTTP %d\n  body: %s\n", resp.StatusCode, b)
		fmt.Println("  进程还活着 —— 这就是 recovery 的全部意义")
	})

	run("4. 已写响应头之后再 panic → body 被追加，这就是「已写头不能再写」", func() {
		resp, err := http.Get(ts.URL + "/api/homeos/boom-after-write")
		if err != nil {
			fmt.Println("  ERR:", err)
			return
		}
		defer resp.Body.Close()
		b, _ := io.ReadAll(resp.Body)
		fmt.Printf("  HTTP %d\n  body: %s\n", resp.StatusCode, b)
		fmt.Println("  看到没有：合法的 JSON 后面被硬接了一段东西，前端 JSON.parse 会炸")
		fmt.Println("  对策：handler 里先组装好再写，绝不写一半就 panic（见 d4 的分层）")
	})

	run("5. 静默的 404 也会留下日志（NoRoute 也经过中间件链）", func() {
		resp, err := http.Get(ts.URL + "/api/nope")
		if err != nil {
			fmt.Println("  ERR:", err)
			return
		}
		defer resp.Body.Close()
		b, _ := io.ReadAll(resp.Body)
		fmt.Printf("  HTTP %d  body: %s\n", resp.StatusCode, b)
	})

	fmt.Println("=== S2 d3 到此结束 ===")
	fmt.Println("注意每条日志都带 request_id —— 这是 d3 存在的全部理由。")
	log.SetOutput(io.Discard) // 不让默认 logger 干扰输出
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strings"
)

// =====================================================================
// 今天把 d1-d3 的「一个 handler 干所有事」重构成四层。
// 真实项目是 4 个包，这里为了能 go run 放一个文件，用注释标出每个类型属于哪个包。
// =====================================================================

// =====================================================================
// 第 1 层：model —— 领域实体。放internal/homeos/model/category.go
// 它只描述「数据长什么样」，不含任何 json tag、不含任何校验规则、不含任何逻辑。
// =====================================================================

// Category 是领域模型。它**没有 json tag**——因为它不是给前端看的。
type Category struct {
	ID        int64
	FamilyID  int64
	Name      string
	ParentID  *int64 // 可空：一级分类没有父分类
	Type      string // expense | income
	SortOrder int
	IsActive  bool
}

// DomainError：业务错误。放 internal/homeos/service/errors.go
// service 层抛，handler 层翻译成响应。repo 层不认识它。
type DomainError struct {
	Code    int
	Message string
}

func (e *DomainError) Error() string { return e.Message }

// 业务错误码。tech-plan §6.2 的 4001/4002 段。
var (
	ErrCategoryNotFound = &DomainError{Code: 4001, Message: "分类不存在"}
	ErrInactiveCategory = &DomainError{Code: 4002, Message: "分类已停用"}
	ErrDuplicateName    = &DomainError{Code: 4003, Message: "同级下分类名重复"}
)

// =====================================================================
// 第 2 层：repo —— 数据访问。放 internal/homeos/repo/category.go
// 只碰本 schema，只做单表 CRUD。它**不认识** DomainError，
// 也不该认识——「同名重复」是业务规则，不是存储事实。
// =====================================================================

// CategoryRepo 是接口。service 依赖接口而不是具体实现，
// 所以 d6 换成内存实现、S3 换成 Postgres 实现时service 一行不改。
type CategoryRepo interface {
	Insert(c *Category) error
	Update(c *Category) error
	Delete(id, familyID int64) error
	FindByID(id, familyID int64) (*Category, error)
	FindByName(name string, familyID int64, parentID *int64) (*Category, error)
	ListByFamily(familyID int64) ([]Category, error)
}

type memCategoryRepo struct {
	items map[int64]*Category
	seq   int64
}

func newMemCategoryRepo() *memCategoryRepo {
	return &memCategoryRepo{items: map[int64]*Category{}}
}

func (r *memCategoryRepo) Insert(c *Category) error {
	r.seq++
	c.ID = r.seq
	// 存的是**副本**。repo 边界就是一道防线：调用方之后改自己的
	// struct 不会影响仓库里的数据。这在 JS 里靠 freeze，在 Go 里靠值语义。
	r.items[c.ID] = &Category{}
	*r.items[c.ID] = *c
	return nil
}

func (r *memCategoryRepo) Update(c *Category) error {
	if _, ok := r.items[c.ID]; !ok {
		return errors.New("repo: id 不存在")
	}
	r.items[c.ID] = &Category{}
	*r.items[c.ID] = *c
	return nil
}

func (r *memCategoryRepo) Delete(id, familyID int64) error {
	for k, v := range r.items {
		if k == id && v.FamilyID == familyID {
			delete(r.items, k)
			return nil
		}
	}
	return errors.New("repo: id 不存在")
}

// FindByID 演示多租户：familyID 是**每个查询方法的必填参数**，不是可选过滤器。
func (r *memCategoryRepo) FindByID(id, familyID int64) (*Category, error) {
	v, ok := r.items[id]
	if !ok {
		return nil, errors.New("repo: not found")
	}
	// 注意：id 对但 family 不对，也要报 not found。
	// 这是 S3/W12 多租户隔离的核心——不能因为 id 存在就返回数据。
	if v.FamilyID != familyID {
		return nil, errors.New("repo: not found")
	}
	cp := *v
	return &cp, nil
}

func (r *memCategoryRepo) FindByName(name string, familyID int64, parentID *int64) (*Category, error) {
	for _, v := range r.items {
		if v.Name == name && v.FamilyID == familyID && sameParent(v.ParentID, parentID) {
			cp := *v
			return &cp, nil
		}
	}
	return nil, errors.New("repo: not found")
}

func sameParent(a, b *int64) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	return *a == *b
}

func (r *memCategoryRepo) ListByFamily(familyID int64) ([]Category, error) {
	out := []Category{}
	for _, v := range r.items {
		if v.FamilyID == familyID {
			out = append(out, *v)
		}
	}
	// map 遍历顺序随机，必须显式排序，否则输出不可复现（S1 d10 的坑）。
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out, nil
}

// =====================================================================
// 第 3 层：service —— 业务编排。放 internal/homeos/service/category.go
// 它做三件handler 和 repo 都做不了的事：
//   ① 跨表/多次写的一致性  ② 业务规则判定  ③ 事务边界（d4 没有，S3 d11 加）
// =====================================================================

type CategoryService struct {
	repo CategoryRepo
	// familyID 在 S4/S5 会从 context 取（token 里的 fam），
	// 现在先作为参数传，让「多租户从哪来」这件事显式可见。
}

func NewCategoryService(repo CategoryRepo) *CategoryService {
	return &CategoryService{repo: repo}
}

type CreateCategoryInput struct {
	FamilyID int64
	Name     string
	ParentID *int64
	Type     string
}

func (s *CategoryService) Create(in CreateCategoryInput) (*Category, error) {
	name := strings.TrimSpace(in.Name)
	if name == "" {
		return nil, &DomainError{Code: 1002, Message: "分类名不能为空"}
	}
	if in.Type != "expense" && in.Type != "income" {
		return nil, &DomainError{Code: 1002, Message: "type 只能是 expense 或 income"}
	}
	// 业务规则①：同级同名不允许。
	// 这是**业务规则**，所以判定放在 service，不放 repo。
	if existing, err := s.repo.FindByName(name, in.FamilyID, in.ParentID); err == nil && existing != nil {
		return nil, ErrDuplicateName
	}

	c := &Category{
		FamilyID: in.FamilyID,
		Name:     name,
		ParentID: in.ParentID,
		Type:     in.Type,
		IsActive: true,
	}
	if err := s.repo.Insert(c); err != nil {
		return nil, err // repo 的错误原样往上抛
	}
	return c, nil
}

func (s *CategoryService) Deactivate(id, familyID int64) error {
	c, err := s.repo.FindByID(id, familyID)
	if err != nil {
		return ErrCategoryNotFound // repo 的技术错误在这里翻译成业务错误
	}
	if !c.IsActive {
		return ErrInactiveCategory
	}
	c.IsActive = false
	if err := s.repo.Update(c); err != nil {
		return err
	}
	return nil
}

// StopInsteadOfDelete：分类**不提供删除**，只提供停用。
// 理由：历史流水引用了它，删掉会让老数据变成孤儿（tech-plan §5.1 铁律 2）。
func (s *CategoryService) StopInsteadOfDelete(id, familyID int64) error {
	return s.Deactivate(id, familyID)
}

func (s *CategoryService) List(familyID int64) ([]Category, error) {
	return s.repo.ListByFamily(familyID)
}

// =====================================================================
// 第 4 层：handler —— HTTP 适配。放 internal/homeos/handler/category.go
// 它只做四件事：解析请求 → 调 service → 把 error 翻译成 HTTP → 组装响应。
// 它**不写业务分支**，也**不碰 repo**。
// =====================================================================

type CreateCategoryRequest struct {
	Name     string `json:"name"`
	ParentID *int64 `json:"parent_id"`
	Type     string `json:"type"`
}

type CreateCategoryResponse struct {
	ID       int64  `json:"id"`
	Name     string `json:"name"`
	Type     string `json:"type"`
	IsActive bool   `json:"is_active"`
}

// CategoryHandler 持有 service。**它拿不到 repo** —— 这就是分层的强制力。
type CategoryHandler struct {
	svc *CategoryService
}

func NewCategoryHandler(svc *CategoryService) *CategoryHandler {
	return &CategoryHandler{svc: svc}
}

func (h *CategoryHandler) Create(familyID int64, req CreateCategoryRequest) (int, any, error) {
	c, err := h.svc.Create(CreateCategoryInput{
		FamilyID: familyID,
		Name:     req.Name,
		ParentID: req.ParentID,
		Type:     req.Type,
	})
	if err != nil {
		// handler 在这里做唯一一件事：把 error 翻译成 HTTP。
		// 判定用 errors.As（S1 d16 讲的），不是 == 或字符串匹配。
		var de *DomainError
		if errors.As(err, &de) {
			return statusFor(de.Code), map[string]any{"code": de.Code, "message": de.Message}, nil
		}
		return 500, map[string]any{"code": 5000, "message": "服务端错误"}, nil
	}
	return 201, CreateCategoryResponse{
		ID:       c.ID,
		Name:     c.Name,
		Type:     c.Type,
		IsActive: c.IsActive,
	}, nil
}

func statusFor(code int) int {
	switch code {
	case 1002:
		return 422
	case 4001, 4002, 4003:
		return 409
	}
	return 500
}

// =====================================================================
// 装配：main.go 里只做这件事——把各层 new 出来接在一起。
// 这就是「进程入口只做装配」的意思（tech-plan §3.1）。
// =====================================================================

func main() {
	repo := newMemCategoryRepo()
	svc := NewCategoryService(repo)
	h := NewCategoryHandler(svc)

	fmt.Println("=== 1. 正常创建（family_id = 1）===")
	show(h.Create(1, CreateCategoryRequest{Name: "餐饮", Type: "expense"}))
	fmt.Println("\n=== 2. 创建子分类（parent_id = 1）===")
	parentID := int64(1)
	show(h.Create(1, CreateCategoryRequest{Name: "午餐", Type: "expense", ParentID: &parentID}))
	fmt.Println("\n=== 3. 同级同名 → 业务错误 4003（service 判的，不是 repo）===")
	show(h.Create(1, CreateCategoryRequest{Name: "餐饮", Type: "expense"}))

	fmt.Println("\n=== 4. 另一个 family 用同一个 repo：各自只能看到自己的数据 ===")
	show(h.Create(2, CreateCategoryRequest{Name: "买菜", Type: "expense"})) // B 家用自己的名字
	// B 家试图读 A 家的分类（走 svc.List 会看到只有 B 家的）
	show(h.Create(2, CreateCategoryRequest{Name: "交通", Type: "expense"}))

	fmt.Println("\n=== 5. 非法 type → 1002 / 422 ===")
	show(h.Create(1, CreateCategoryRequest{Name: "娱乐", Type: "unknown"}))

	fmt.Println("\n=== 6. 停用而非删除 ===")
	err := h.svc.StopInsteadOfDelete(1, 1)
	fmt.Printf("  StopInsteadOfDelete(1) → %v\n", err)
	err = h.svc.StopInsteadOfDelete(1, 1)
	fmt.Printf("  再停一次 → %v（第二次就报 4002 已停用）\n", err)

	fmt.Println("\n=== 7. 各family 看到的列表（多租户过滤在 repo 里生效）===")
	for _, fam := range []int64{1, 2} {
		items, _ := svc.List(fam)
		names := []string{}
		for _, it := range items {
			names = append(names, fmt.Sprintf("%d:%s(active=%v)", it.ID, it.Name, it.IsActive))
		}
		fmt.Printf("  family %d → %v\n", fam, names)
	}

	fmt.Println("\n=== S2 d4 到此结束 ===")
	fmt.Println("注意 handler 里没有任何 if businessRule、没有 map[string]any 的存储访问。")
	fmt.Println("d5 给这四层写测试；d6 补齐 6 条接口并确认没有跨层调用。")
}

// show 用 JSON 打印响应体，和真实 HTTP 输出对齐（Go 的 %v 打struct
// 打出来是 Go 语法 `{1 餐饮 expense true}`，前端根本看不懂）。
func show(stage int, data any, err error) {
	if err != nil {
		fmt.Printf("  err=%v\n", err)
		return
	}
	b, _ := json.Marshal(map[string]any{"code": 0, "data": data})
	fmt.Printf("  HTTP %d  %s\n", stage, b)
}

