package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

// =====================================================================
// httptest：不起真实端口、不发真实网络包，直接把「请求」喂给 handler。
// 对比 d1~d4 用的 httptest.NewServer：
//   NewServer  → 真起 net/http 服务器 + 真 socket，请求走完整内核网络栈
//   NewRecorder→ 只在内存里造一个假 ResponseWriter，不碰网络
// 前者适合「冒烟」，后者适合「单元测试」：快、确定、不受端口占用影响。
// =====================================================================

// ---- 被测的四层（和 d4 一样，真实项目拆4 个包）----

type Category struct {
	ID       int64
	FamilyID int64
	Name     string
	Type     string
	IsActive bool
}

type DomainError struct {
	Code    int
	Message string
}

func (e *DomainError) Error() string { return e.Message }

var ErrDuplicate = &DomainError{Code: 4003, Message: "同级下分类名重复"}

// repo 层
type CategoryRepo interface {
	Insert(c *Category) error
	FindByName(name string, familyID int64) (*Category, error)
	ListByFamily(familyID int64) ([]Category, error)
}

type memRepo struct {
	items map[int64]*Category
	seq   int64
}

func newMemRepo() *memRepo { return &memRepo{items: map[int64]*Category{}} }

func (r *memRepo) Insert(c *Category) error {
	r.seq++
	c.ID = r.seq
	cp := *c
	r.items[c.ID] = &cp
	return nil
}

func (r *memRepo) FindByName(name string, familyID int64) (*Category, error) {
	for _, v := range r.items {
		if v.Name == name && v.FamilyID == familyID {
			cp := *v
			return &cp, nil
		}
	}
	return nil, fmt.Errorf("repo: not found")
}

func (r *memRepo) ListByFamily(familyID int64) ([]Category, error) {
	out := []Category{}
	for _, v := range r.items {
		if v.FamilyID == familyID {
			out = append(out, *v)
		}
	}
	return out, nil
}

// service 层
type CategoryService struct{ repo CategoryRepo }

func NewCategoryService(r CategoryRepo) *CategoryService { return &CategoryService{repo: r} }

func (s *CategoryService) Create(familyID int64, name, typ string) (*Category, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return nil, &DomainError{Code: 1002, Message: "分类名不能为空"}
	}
	if typ != "expense" && typ != "income" {
		return nil, &DomainError{Code: 1002, Message: "type 非法"}
	}
	if got, _ := s.repo.FindByName(name, familyID); got != nil {
		return nil, ErrDuplicate
	}
	c := &Category{FamilyID: familyID, Name: name, Type: typ, IsActive: true}
	if err := s.repo.Insert(c); err != nil {
		return nil, err
	}
	return c, nil
}

// handler 层 + 统一响应体
type Envelope struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
	Data    any    `json:"data"`
}

type CreateReq struct {
	Name string `json:"name"`
	Type string `json:"type"`
}

type CreateResp struct {
	ID       int64  `json:"id"`
	Name     string `json:"name"`
	IsActive bool   `json:"is_active"`
}

type CategoryHandler struct{ svc *CategoryService }

func NewCategoryHandler(s *CategoryService) *CategoryHandler { return &CategoryHandler{svc: s} }

func (h *CategoryHandler) Create(c *gin.Context) {
	var req CreateReq
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, Envelope{Code: 1001, Message: "请求体不是合法 JSON"})
		return
	}
	// 现在还没鉴权，先写死 family 1。S4/S5 会从 token 里取。
	cat, err := h.svc.Create(1, req.Name, req.Type)
	if err != nil {
		var de *DomainError
		if asDomain(err, &de) {
			status := 422
			if de.Code != 1002 {
				status = 409
			}
			c.JSON(status, Envelope{Code: de.Code, Message: de.Message})
			return
		}
		c.JSON(http.StatusInternalServerError, Envelope{Code: 5000, Message: "服务端错误"})
		return
	}
	c.JSON(http.StatusCreated, Envelope{Code: 0, Message: "ok", Data: CreateResp{ID: cat.ID, Name: cat.Name, IsActive: cat.IsActive}})
}

func asDomain(err error, target **DomainError) bool {
	if de, ok := err.(*DomainError); ok {
		*target = de
		return true
	}
	return false
}

func BuildRouter() *gin.Engine {
	r := gin.New()
	h := NewCategoryHandler(NewCategoryService(newMemRepo()))
	api := r.Group("/api/homeos")
	api.POST("/categories", h.Create)
	return r
}

// collector：收集测试结果的小工具，能把通过/失败打印出来。
type collector struct {
	name     string
	passed   int
	failed   int
	failures []string
}

func (c *collector) Errorf(format string, args ...any) {
	c.failed++
	c.failures = append(c.failures, fmt.Sprintf(format, args...))
}
func (c *collector) Fatalf(format string, args ...any) {
	c.failed++
	c.failures = append(c.failures, fmt.Sprintf(format, args...))
}
func (c *collector) Error(args ...any) {
	c.failed++
	c.failures = append(c.failures, fmt.Sprint(args...))
}
func (c *collector) Fatal(args ...any) {
	c.failed++
	c.failures = append(c.failures, fmt.Sprint(args...))
}
func (c *collector) Log(args ...any)         {}
func (c *collector) Logf(f string, a ...any) {}
func (c *collector) Helper()                 {}
func (c *collector) Name() string            { return c.name }
func (c *collector) Skip(args ...any)        {}
func (c *collector) Parallel()               {}

func (c *collector) Equal(got, want any, label string) {
	g, w := fmt.Sprintf("%v", got), fmt.Sprintf("%v", want)
	if g == w {
		c.passed++
	} else {
		c.failed++
		c.failures = append(c.failures, fmt.Sprintf("%s: got=%s want=%s", label, g, w))
	}
}

func (c *collector) report() bool {
	status := "✅ PASS"
	if c.failed > 0 {
		status = "❌ FAIL"
	}
	fmt.Printf("%s  %s  (断言 %d 条, 失败 %d 条)\n", status, c.name, c.passed+c.failed, c.failed)
	for _, f := range c.failures {
		fmt.Println("       ↳ " + f)
	}
	return c.failed == 0
}

// checkHealthz / checkCreate / checkService 是「不用 testing.T」的版本，
// 它们只用 collector.Equal 做断言。真实项目里这些逻辑就是 *_test.go 的内容，
// 差别只是断言换成 t.Errorf / require.Equal。
func checkHealthz() bool {
	c := &collector{name: "TestHealthz_Recorder"}
	r := gin.New()
	r.GET("/healthz", func(ctx *gin.Context) {
		ctx.JSON(http.StatusOK, Envelope{Code: 0, Message: "ok", Data: gin.H{"status": "up"}})
	})
	w := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/healthz", nil)
	r.ServeHTTP(w, req)
	c.Equal(w.Code, 200, "status")
	c.Equal(strings.Contains(w.Body.String(), `"status":"up"`), true, "body 含 status=up")
	return c.report()
}

func checkCreate() bool {
	c := &collector{name: "TestCreateCategory_接口测试"}
	r := BuildRouter()
	cases := []struct {
		name       string
		body       string
		wantStatus int
		wantMsg    string
	}{
		{"正常创建", `{"name":"餐饮","type":"expense"}`, 201, ""},
		{"空名字", `{"name":"","type":"expense"}`, 422, "分类名不能为空"},
		{"非法 type", `{"name":"娱乐","type":"xxx"}`, 422, "type 非法"},
		{"重复创建", `{"name":"餐饮","type":"expense"}`, 409, "同级下分类名重复"},
		{"JSON 语法错", `{"name":}`, 400, "请求体不是合法 JSON"},
	}
	for _, tc := range cases {
		w := httptest.NewRecorder()
		req := httptest.NewRequest(http.MethodPost, "/api/homeos/categories", strings.NewReader(tc.body))
		req.Header.Set("Content-Type", "application/json")
		r.ServeHTTP(w, req)
		c.Equal(w.Code, tc.wantStatus, tc.name+" 状态码")
		var env Envelope
		if err := json.Unmarshal(w.Body.Bytes(), &env); err != nil {
			c.failed++
			c.failures = append(c.failures, tc.name+" 响应体不是 JSON: "+w.Body.String())
			continue
		}
		if tc.wantMsg != "" {
			c.Equal(env.Message, tc.wantMsg, tc.name+" message")
		}
	}
	return c.report()
}

