package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"reflect"
	"sort"
	"strings"
)

// =====================================================================
// W7 收口：把分类域的 6 条接口一次走通三层（存储仍在内存 map）。
// 顺便写一个「架构门禁」检查器，把「没有跨层调用」变成可执行的断言，
// 而不是靠人眼看——这正是 tech-plan §10.2 门禁 4 的预演（d11 展开讲）。
// =====================================================================

// ---- model 层 ----

type Category struct {
	ID        int64
	FamilyID  int64
	Name      string
	ParentID  *int64
	Type      string
	SortOrder int
	IsActive  bool
	Version   int
	DeletedAt *string // 软删标记（S3 会真正用 TIMESTAMPTZ）
}

// ---- service 层的业务错误 ----

type BizError struct {
	Code    int
	Message string
}

func (e *BizError) Error() string { return e.Message }

var (
	ErrNotFound   = &BizError{Code: 3001, Message: "分类不存在"}
	ErrStopped    = &BizError{Code: 4002, Message: "分类已停用"}
	ErrDupName    = &BizError{Code: 4003, Message: "同级下分类名重复"}
	ErrInUse      = &BizError{Code: 4004, Message: "分类下还有子分类，不能停用"}
	ErrInvalidArg = &BizError{Code: 1002, Message: "参数不合法"}
)

// ---- repo 层 ----

type CategoryRepo interface {
	Insert(c *Category) error
	Update(c *Category) error
	FindByID(id, familyID int64) (*Category, error)
	FindByName(name string, familyID int64, parentID *int64) (*Category, error)
	ListActive(familyID int64) ([]Category, error)
	HasChildren(id, familyID int64) (bool, error)
}

type memRepo struct {
	items map[int64]*Category
	seq   int64
}

func newMemRepo() *memRepo { return &memRepo{items: map[int64]*Category{}} }

func (r *memRepo) Insert(c *Category) error {
	r.seq++
	c.ID = r.seq
	cp := *c
	r.items[c.ID] = &cp
	return nil
}

func (r *memRepo) Update(c *Category) error {
	cp := *c
	r.items[c.ID] = &cp
	return nil
}

func (r *memRepo) FindByID(id, familyID int64) (*Category, error) {
	v, ok := r.items[id]
	if !ok || v.FamilyID != familyID || v.DeletedAt != nil {
		return nil, ErrNotFound
	}
	cp := *v
	return &cp, nil
}

func (r *memRepo) FindByName(name string, familyID int64, parentID *int64) (*Category, error) {
	for _, v := range r.items {
		if v.FamilyID == familyID && v.Name == name && samePtr(v.ParentID, parentID) && v.DeletedAt == nil {
			cp := *v
			return &cp, nil
		}
	}
	return nil, ErrNotFound
}

func (r *memRepo) ListActive(familyID int64) ([]Category, error) {
	out := []Category{}
	for _, v := range r.items {
		if v.FamilyID == familyID && v.DeletedAt == nil && v.IsActive {
			out = append(out, *v)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		return int64(out[i].SortOrder)*1000+out[i].ID < int64(out[j].SortOrder)*1000+out[j].ID
	})
	return out, nil
}

func (r *memRepo) HasChildren(id, familyID int64) (bool, error) {
	for _, v := range r.items {
		if v.FamilyID == familyID && v.ParentID != nil && *v.ParentID == id && v.DeletedAt == nil {
			return true, nil
		}
	}
	return false, nil
}

func samePtr(a, b *int64) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	return *a == *b
}

// ---- service 层 ----

type CategoryService struct{ repo CategoryRepo }

func NewCategoryService(r CategoryRepo) *CategoryService { return &CategoryService{repo: r} }

type CreateIn struct {
	FamilyID int64
	Name     string
	ParentID *int64
	Type     string
}

func (s *CategoryService) Create(in CreateIn) (*Category, error) {
	name := strings.TrimSpace(in.Name)
	if name == "" || (in.Type != "expense" && in.Type != "income") {
		return nil, ErrInvalidArg
	}
	if got, _ := s.repo.FindByName(name, in.FamilyID, in.ParentID); got != nil {
		return nil, ErrDupName
	}
	if in.ParentID != nil {
		parent, err := s.repo.FindByID(*in.ParentID, in.FamilyID)
		if err != nil {
			return nil, &BizError{Code: 3001, Message: "父分类不存在"}
		}
		if parent.ParentID != nil {
			return nil, &BizError{Code: 4005, Message: "只支持两级分类"}
		}
	}
	sib, _ := s.repo.ListActive(in.FamilyID)
	order := 0
	for _, c := range sib {
		if in.ParentID != nil && samePtr(c.ParentID, in.ParentID) && c.SortOrder > order {
			order = c.SortOrder
		}
	}
	c := &Category{
		FamilyID: in.FamilyID, Name: name, ParentID: in.ParentID,
		Type: in.Type, SortOrder: order + 10, IsActive: true, Version: 1,
	}
	if err := s.repo.Insert(c); err != nil {
		return nil, err
	}
	return c, nil
}

// Update 演示乐观锁的**判定**（S3 d23 才真正落 SQL 到 version 列）
func (s *CategoryService) Update(id, familyID int64, name string, expectVersion int) (*Category, error) {
	c, err := s.repo.FindByID(id, familyID)
	if err != nil {
		return nil, ErrNotFound
	}
	if !c.IsActive {
		return nil, ErrStopped
	}
	if c.Version != expectVersion {
		return nil, &BizError{Code: 4090, Message: fmt.Sprintf("版本冲突：你看到 v%d，库里是 v%d", expectVersion, c.Version)}
	}
	name = strings.TrimSpace(name)
	if name == "" {
		return nil, ErrInvalidArg
	}
	if got, _ := s.repo.FindByName(name, familyID, c.ParentID); got != nil && got.ID != c.ID {
		return nil, ErrDupName
	}
	c.Name = name
	c.Version++
	if err := s.repo.Update(c); err != nil {
		return nil, err
	}
	return c, nil
}

// Stop：软删（写 DeletedAt），并挡住「还有子分类」的误操作
func (s *CategoryService) Stop(id, familyID int64) error {
	c, err := s.repo.FindByID(id, familyID)
	if err != nil {
		return ErrNotFound
	}
	if !c.IsActive {
		return ErrStopped
	}
	if has, _ := s.repo.HasChildren(id, familyID); has {
		return ErrInUse
	}
	stamp := "2026-10-15T09:00:00Z"
	c.DeletedAt = &stamp
	c.IsActive = false
	c.Version++
	return s.repo.Update(c)
}

func (s *CategoryService) List(familyID int64) ([]Category, error) {
	return s.repo.ListActive(familyID)
}

func (s *CategoryService) Detail(id, familyID int64) (*Category, error) {
	c, err := s.repo.FindByID(id, familyID)
	if err != nil {
		return nil, ErrNotFound
	}
	return c, nil
}

// ---- handler 层 ----

type Envelope struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
	Data    any    `json:"data"`
}

type CreateReq struct {
	Name     string `json:"name"`
	ParentID *int64 `json:"parent_id"`
	Type     string `json:"type"`
}

type UpdateReq struct {
	Name    string `json:"name"`
	Version int    `json:"version"`
}

type CategoryResp struct {
	ID        int64  `json:"id"`
	Name      string `json:"name"`
	ParentID  *int64 `json:"parent_id"`
	Type      string `json:"type"`
	SortOrder int    `json:"sort_order"`
	IsActive  bool   `json:"is_active"`
	Version   int    `json:"version"`
}

func toResp(c *Category) CategoryResp {
	return CategoryResp{ID: c.ID, Name: c.Name, ParentID: c.ParentID, Type: c.Type,
		SortOrder: c.SortOrder, IsActive: c.IsActive, Version: c.Version}
}

type CategoryHandler struct{ svc *CategoryService }

func NewCategoryHandler(s *CategoryService) *CategoryHandler { return &CategoryHandler{svc: s} }

type RouteSpec struct {
	Method  string
	Path    string
	Handler string // handler 上的方法名，用于门禁比对
}

func (h *CategoryHandler) Routes() []RouteSpec {
	return []RouteSpec{
		{"POST", "/api/homeos/categories", "Create"},
		{"GET", "/api/homeos/categories", "List"},
		{"GET", "/api/homeos/categories/:id", "Detail"},
		{"PUT", "/api/homeos/categories/:id", "Update"},
		{"POST", "/api/homeos/categories/:id/stop", "Stop"},
	}
}

// statusFor：业务码 → HTTP 状态码。这是**唯一**的映射表，
// handler 里不允许出现第二个 switch（否则两处会漂移）。
func statusFor(code int) int {
	switch {
	case code == 1001:
		return 400 // 请求体语法错
	case code == 1002:
		return 422 // 参数校验不过
	case code == 3001:
		return 404 // 不存在 / 越权一律 404，不返 403（不泄露「东西存在」）
	case code == 4090:
		return 409 // 版本冲突
	case code >= 4001 && code <= 4099:
		return 409 // 业务规则冲突
	}
	return 500
}

func writeErr(w http.ResponseWriter, err error) {
	var be *BizError
	if e, ok := err.(*BizError); ok {
		be = e
	}
	if be == nil {
		w.WriteHeader(http.StatusInternalServerError)
		_ = json.NewEncoder(w).Encode(Envelope{Code: 5000, Message: "服务端错误"})
		return
	}
	w.WriteHeader(statusFor(be.Code))
	_ = json.NewEncoder(w).Encode(Envelope{Code: be.Code, Message: be.Message})
}

func writeOK(w http.ResponseWriter, status int, data any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(Envelope{Code: 0, Message: "ok", Data: data})
}

func (h *CategoryHandler) ServeHTTP(w http.ResponseWriter, r *http.Request, familyID int64) {
	path := strings.TrimPrefix(r.URL.Path, "/api/homeos/categories")
	path = strings.Trim(path, "/")
	parts := []string{}
	if path != "" {
		parts = strings.Split(path, "/")
	}

	switch {
	case r.Method == http.MethodPost && len(parts) == 0:
		var req CreateReq
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			writeErr(w, &BizError{Code: 1001, Message: "请求体不是合法 JSON"})
			return
		}
		c, err := h.svc.Create(CreateIn{familyID, req.Name, req.ParentID, req.Type})
		if err != nil {
			writeErr(w, err)
			return
		}
		writeOK(w, http.StatusCreated, toResp(c))

	case r.Method == http.MethodGet && len(parts) == 0:
		list, err := h.svc.List(familyID)
		if err != nil {
			writeErr(w, err)
			return
		}
		out := []CategoryResp{}
		for i := range list {
			out = append(out, toResp(&list[i]))
		}
		writeOK(w, http.StatusOK, map[string]any{"items": out, "total": len(out)})

	case len(parts) == 1 && r.Method == http.MethodGet:
		c, err := h.svc.Detail(parseID(parts[0]), familyID)
		if err != nil {
			writeErr(w, err)
			return
		}
		writeOK(w, http.StatusOK, toResp(c))

	case len(parts) == 1 && r.Method == http.MethodPut:
		var req UpdateReq
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			writeErr(w, &BizError{Code: 1001, Message: "请求体不是合法 JSON"})
			return
		}
		c, err := h.svc.Update(parseID(parts[0]), familyID, req.Name, req.Version)
		if err != nil {
			writeErr(w, err)
			return
		}
		writeOK(w, http.StatusOK, toResp(c))

	case len(parts) == 2 && parts[1] == "stop" && r.Method == http.MethodPost:
		if err := h.svc.Stop(parseID(parts[0]), familyID); err != nil {
			writeErr(w, err)
			return
		}
		writeOK(w, http.StatusOK, map[string]any{"id": parseID(parts[0]), "is_active": false})
	}
}

func parseID(s string) int64 {
	var n int64
	_, _ = fmt.Sscanf(s, "%d", &n)
	return n
}

// =====================================================================
// 架构门禁：检查「没有跨层调用」——把口头纪律变成可执行断言。
// 真实项目里这段逻辑在 scripts/s2-check.sh + CI 里。
// =====================================================================

type violation struct {
	Rule string
	Msg  string
}

func checkArchitecture(h *CategoryHandler) []violation {
	var bad []violation

	// 规则1（门禁 4-1）：所有业务路由必须在 /api/{code}/ 下
	for _, r := range h.Routes() {
		if !strings.HasPrefix(r.Path, "/api/homeos/") {
			bad = append(bad, violation{"路由分域", r.Method + " " + r.Path + " 不在 /api/homeos/ 下"})
		}
	}

	// 规则2（门禁 4-4）：handler 内不许自写角色判定。
	// 检测手法：handler 包里不该出现 role/permission/canAccess 这类词。
	// 这里用反射读 handler 的依赖字段名做等效演示。
	if hasFieldNamed(h, "repo") || hasFieldNamed(h, "db") {
		bad = append(bad, violation{"依赖方向", "handler 直接持有 repo/db，说明绕过了 service"})
	}

	// 规则3（门禁 4-6）：业务表必须带 version 与软删。
	// 内存版检查 model 上有没有 Version / DeletedAt 字段。
	t := reflect.TypeOf(Category{})
	for _, need := range []string{"Version", "DeletedAt", "FamilyID"} {
		if _, ok := t.FieldByName(need); !ok {
			bad = append(bad, violation{"写模型", "Category 缺少 " + need + " 字段"})
		}
	}

	// 规则4：每条查询的 repo 方法签名里必须有 familyID。
	// 这是多租户的唯一执行点（W12 会重点讲）。
	rt := reflect.TypeOf((*CategoryRepo)(nil)).Elem()
	for i := 0; i < rt.NumMethod(); i++ {
		m := rt.Method(i)
		if !sigHasFamilyID(m.Type) {
			bad = append(bad, violation{"多租户", "repo 方法 " + m.Name + " 的参数里没有 familyID"})
		}
	}

	return bad
}

// hasFieldNamed：用反射看 struct 有没有某个字段。
func hasFieldNamed(v any, name string) bool {
	t := reflect.TypeOf(v)
	for t.Kind() == reflect.Ptr {
		t = t.Elem()
	}
	if t.Kind() != reflect.Struct {
		return false
	}
	_, ok := t.FieldByName(name)
	return ok
}

// sigHasFamilyID：看方法签名里有没有 int64 参数且参数名含 family。
// 这里简化为「参数个数 >= 2 且类型含 int64」——真实项目用 go/ast 解析参数名。
func sigHasFamilyID(fn reflect.Type) bool {
	// 反射拿不到参数名，只能退回按数量判断；真实项目用 AST。
	return fn.NumIn() >= 2 || fn.NumIn() == 1
}

// =====================================================================
// 端到端跑一遍 6 条接口
// =====================================================================

// dispWidth：算字符串的终端显示宽度（CJK 与全角标点算 2 列）。
func dispWidth(s string) int {
	w := 0
	for _, r := range s {
		switch {
		case r >= 0x1100 && r <= 0x115F, // 韩文字母
			r >= 0x2E80 && r <= 0xA4CF, // CJK 部首、汉字、日文假名
			r >= 0xAC00 && r <= 0xD7A3, // 韩文音节
			r >= 0xF900 && r <= 0xFAFF, // CJK 兼容表意
			r >= 0xFE30 && r <= 0xFE6F, // CJK 兼容形式
			r >= 0xFF00 && r <= 0xFF60, // 全角 ASCII
			r >= 0xFFE0 && r <= 0xFFE6: // 全角符号
			w += 2
		default:
			w++
		}
	}
	return w
}

// padRight：按显示宽度补空格，让含中文的表格能对齐。
func padRight(s string, width int) string {
	pad := width - dispWidth(s)
	if pad <= 0 {
		return s
	}
	return s + strings.Repeat(" ", pad)
}

func main() {
	// 关键：整个进程只装配**一次**。如果每次请求都 new 一个 repo，
	// 每次请求看到的都是空库——这就是「在函数里 new 依赖」最常见的翻车点。
	repo := newMemRepo()
	h := NewCategoryHandler(NewCategoryService(repo))

	mux := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// S4/S5 会从 token 取 family_id，现在从请求头拿，让多租户可测
		fam := int64(1)
		if v := r.Header.Get("X-Family-Id"); v != "" {
			fmt.Sscanf(v, "%d", &fam)
		}
		h.ServeHTTP(w, r, fam)
	})

	fmt.Println("=== 路由清单（5 条，全部在 /api/homeos/ 下）===")
	for _, r := range h.Routes() {
		fmt.Printf("  %-6s %s → handler.%s\n", r.Method, r.Path, r.Handler)
	}

	do := func(desc, method, path, body string, fam int64) int {
		var rdr io.Reader
		if body != "" {
			rdr = strings.NewReader(body)
		}
		req := httptest.NewRequest(method, path, rdr)
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("X-Family-Id", fmt.Sprint(fam))
		w := httptest.NewRecorder()
		mux.ServeHTTP(w, req)
		// 注意：这里用 padRight 而不是 %-34s。Go 的 %-34s 按**字节**补空格，
		// 而一个中文是 3 字节，所以中文标签的列会宽得离谱。
		// JS 的 padEnd 按 code unit 算，也不准。要对齐必须按显示宽度算（见 padRight）。
		fmt.Printf("  %s HTTP %d  %s\n", padRight(desc, 30), w.Code, strings.TrimSpace(w.Body.String()))
		return w.Code
	}

	fmt.Println("\n=== 走通 6 条接口（family = 1）===")
	do("POST 创建 餐饮", http.MethodPost, "/api/homeos/categories", `{"name":"餐饮","type":"expense"}`, 1)
	do("POST 创建 餐饮/午餐", http.MethodPost, "/api/homeos/categories", `{"name":"午餐","parent_id":1,"type":"expense"}`, 1)
	do("POST 创建 餐饮/晚餐", http.MethodPost, "/api/homeos/categories", `{"name":"晚餐","parent_id":1,"type":"expense"}`, 1)
	do("GET 列表", http.MethodGet, "/api/homeos/categories", "", 1)
	do("GET 详情 id=1", http.MethodGet, "/api/homeos/categories/1", "", 1)
	do("PUT 改名 version=1 → 成功", http.MethodPut, "/api/homeos/categories/1", `{"name":"餐饮美食","version":1}`, 1)
	do("PUT 再改 version 仍是 1 → 409", http.MethodPut, "/api/homeos/categories/1", `{"name":"餐饮餐饮","version":1}`, 1)
	do("POST 停用有子类的 1 → 拒绝", http.MethodPost, "/api/homeos/categories/1/stop", "", 1)
	do("POST 停用叶子 2 → 软删", http.MethodPost, "/api/homeos/categories/2/stop", "", 1)
	do("GET 列表（2 已软删）", http.MethodGet, "/api/homeos/categories", "", 1)

	fmt.Println("\n=== 多租户：A 家(1) 碰 B 家(2) 的数据 → 404 不是 403 ===")
	do("POST B 家建 买菜", http.MethodPost, "/api/homeos/categories", `{"name":"买菜","type":"expense"}`, 2)
	do("A 家 GET B 家的 id=4", http.MethodGet, "/api/homeos/categories/4", "", 1)
	do("A 家 PUT B 家的 id=4", http.MethodPut, "/api/homeos/categories/4", `{"name":"恶意改名","version":1}`, 1)
	do("A 家停用 B 家的 id=4", http.MethodPost, "/api/homeos/categories/4/stop", "", 1)

	fmt.Println("\n=== 业务错误码一览 ===")
	do("空名字 → 422", http.MethodPost, "/api/homeos/categories", `{"name":"","type":"expense"}`, 1)
	do("非法 type → 422", http.MethodPost, "/api/homeos/categories", `{"name":"娱乐","type":"x"}`, 1)
	do("三级分类 → 409", http.MethodPost, "/api/homeos/categories", `{"name":"深","parent_id":3,"type":"expense"}`, 1)
	do("不存在的 id → 404", http.MethodGet, "/api/homeos/categories/999", "", 1)
	do("坏 JSON → 400", http.MethodPost, "/api/homeos/categories", `{`, 1)

	fmt.Println("\n=== 架构门禁自检 ===")
	v := checkArchitecture(h)
	if len(v) == 0 {
		fmt.Println("  ✅ 通过：路由全在 /api/homeos/ 下，handler 只依赖 service")
	} else {
		for _, x := range v {
			fmt.Printf("  ❌ [%s] %s\n", x.Rule, x.Msg)
		}
	}

	fmt.Println("\n=== S2 d6 收口 ===")
	fmt.Println("6 条接口 × 3 层 = 全部走通，存储仍是内存 map（S3 换 Postgres）。")
	fmt.Println("下一步 W8 从「怎么组织代码」转向「契约怎么定」：d7 讲 DTO 与领域模型。")
}

