package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

// =====================================================================
// W8 d7：DTO（对外契约）与领域模型（内部真相）为什么必须是两个 struct。
//
// 核心论点：**同一个 struct 不可能同时是「前端契约」和「数据库真相」**，
// 因为两者的变化原因不同、敏感字段不同、命名规则不同。
// =====================================================================

// =====================================================================
// 三种东西：model（领域模型）/ DTO（传输对象）/ row（数据库行）
// =====================================================================

// ---- model：领域模型。表达业务概念，不关心 JSON，也不关心表结构。----
type Category struct {
	ID        int64
	FamilyID  int64
	Name      string
	ParentID  *int64
	Type      string
	SortOrder int
	IsActive  bool
	Version   int
	// 这些是内部状态，业务上有意义但**不该出现在列表接口**里
	InternalNote string
	CreatedBy    int64
}

// ---- row：数据库行。它是「表长什么样」，和 model 的差异是类型层面。----
// S3 建表后这一层会真实存在：
//
//	category_row{ id uuid, family_id uuid, name varchar(32), sort_order int4, ... }
//
// 注意 id 在 Postgres 是 uuid，扫出来是 [16]byte 或 string，不是 int64。
// 这个「模型类型 ≠ 存储类型」的落差，是 model 层存在的第三个理由。
type categoryRow struct {
	ID        string // uuid
	FamilyID  string // uuid
	Name      string
	SortOrder int32 // int4，比 int 小
	Version   int32
	IsActive  bool
}

// rowToModel：row → model。**转换发生在这里**，而且必须有测试。
func rowToModel(r categoryRow) (*Category, error) {
	return &Category{
		ID:        12345, // 真实实现里这里是 uuid→int64 的转换或直接用 string
		FamilyID:  678,
		Name:      r.Name,
		Type:      "expense",
		SortOrder: int(r.SortOrder),
		IsActive:  r.IsActive,
		Version:   int(r.Version),
	}, nil
}

// =====================================================================
// 为什么不复用？三个硬理由，每个都能独立成灾。
// =====================================================================

// ---- 理由1：敏感字段。model 里有不该给前端的字段。----

// ListResp：列表接口只给前端「渲染列表需要的最少信息」。
type ListResp struct {
	ID        int64  `json:"id"`
	Name      string `json:"name"`
	Type      string `json:"type"`
	SortOrder int    `json:"sort_order"`
	IsActive  bool   `json:"is_active"`
}

// DetailResp：详情接口可以多给几个字段，但仍不给内部状态。
type DetailResp struct {
	ListResp
	ParentID  *int64 `json:"parent_id"`
	Version   int    `json:"version"`
	CreatedBy int64  `json:"created_by"`
	SubCount  int    `json:"sub_count"`
}

// =====================================================================
// 理由2：写入方向上，model 会「反序列化未验证的东西」
// =====================================================================

// CreateReq：前端能传的**全部**。注意它不是 Category 的一部分——
// 它的形状由「产品允许用户改什么」决定，不由「表里有哪些列」决定。
type CreateReq struct {
	Name     string `json:"name"`
	ParentID *int64 `json:"parent_id"`
	Type     string `json:"type"`
}

// ApplyTo：把请求 DTO「翻译」成领域模型，而不是直接反序列化。
// 这是关键一步：family_id 由服务端从 token 取，**绝不从请求体取**。
// 如果你直接 c.ShouldBindJSON(&category)，前端传 {"family_id": 999}
// 就能把数据写进别人家——这是真实的多租户漏洞。
func (req CreateReq) ApplyTo(familyID int64, now int64) (*Category, error) {
	name := strings.TrimSpace(req.Name)
	if name == "" {
		return nil, fmt.Errorf("分类名不能为空")
	}
	if req.Type != "expense" && req.Type != "income" {
		return nil, fmt.Errorf("type 非法")
	}
	// 只取白名单字段构造。CreateReq 里没有 family_id，
	// 所以它**不可能**被前端覆盖——这是「白名单构造」的价值。
	return &Category{
		FamilyID:  familyID, // 来自 token，不是来自请求体
		Name:      name,
		ParentID:  req.ParentID,
		Type:      req.Type,
		SortOrder: 10,
		IsActive:  true,
		Version:   1,
		CreatedBy: now,
	}, nil
}

// =====================================================================
// 理由3：命名规则与演进方向相反
// =====================================================================

// 领域里叫 ParentID（指向父对象）；数据库列可能叫 parent_id（也可能叫
// pid / parent_category_id）；接口里前端习惯叫 parent_id。
// 三者应该能在**各自层里**用最合适的名字，靠转换函数桥接。
// 如果共用一个 struct，你就只能选一个名字，然后另外两处都别扭。

// =====================================================================
// 反例：把三层揉成一个 struct 会发生什么
// =====================================================================

// BadCategory 试图当三个角色：
type BadCategory struct {
	ID        int64  `json:"id"`
	FamilyID  int64  `json:"family_id"` // 危险：前端能传
	ParentID  *int64 `json:"parent_id"`
	Type      string `json:"type"`
	SortOrder int    `json:"sort_order"`
	IsActive  bool   `json:"is_active"` // 危险：前端能改，直接停用别人
	Version   int    `json:"version"`   // 危险：前端能传，乐观锁失效
	Name      string `json:"name"`
	CreatedAt string `json:"created_at"`
	UpdatedAt string `json:"updated_at"`
	// 这些是纯内部字段，但也得打 json tag（因为共用同一个 struct）
	InternalNote  string `json:"internal_note"` // 泄露给前端
	RowVersionRaw int32  `json:"row_version"`   // 存储细节泄露
}

func main() {
	fmt.Println("=== 1. 一个 model 序列化出去，长这样 ===")
	m := &Category{
		ID: 1, FamilyID: 678, Name: "餐饮", Type: "expense",
		SortOrder: 10, IsActive: true, Version: 3,
		InternalNote: "由 owner 手工创建，禁止自动删除", CreatedBy: 42,
	}
	b, _ := json.Marshal(m)
	fmt.Printf("  %s\n", b)
	fmt.Println("  暴露了：internal_note（内部备注）、created_by、family_id")
	fmt.Println("  Go 没 json tag 时默认用字段名，所以 FamilyID → \"FamilyID\"，前端拿到的是 PascalCase")

	fmt.Println("\n=== 2. 换成 DTO 之后 ===")
	resp := DetailResp{
		ListResp: ListResp{ID: 1, Name: "餐饮", Type: "expense", SortOrder: 10, IsActive: true},
		ParentID: nil, Version: 3, CreatedBy: 42, SubCount: 2,
	}
	b2, _ := json.Marshal(resp)
	fmt.Printf("  %s\n", b2)
	fmt.Println("  internal_note 和 family_id 都不在里面了 —— 因为 DTO 里根本没有这些字段")
	fmt.Println("  这不是「忘了删」，是「结构上不可能泄露」")

	fmt.Println("\n=== 3. 写入方向：白名单构造 ===")
	req := CreateReq{Name: "  餐饮  ", Type: "expense"}
	cat, err := req.ApplyTo(9999, 42) // family_id 从 token 来 = 9999
	if err != nil {
		fmt.Println("  err:", err)
	}
	b3, _ := json.Marshal(cat)
	fmt.Printf("  %s\n", b3)
	fmt.Println("  family_id=9999 来自 token，前端无法影响 —— 因为 CreateReq 压根没这个字段")

	fmt.Println("\n=== 4. 反例：直接绑定到 model 会怎样 ===")
	// 模拟前端发来 {"family_id":12345,"is_active":false,"version":99,"name":"恶意改名"}
	evil := `{"family_id":12345,"is_active":false,"version":99,"name":"恶意改名"}`
	var bad BadCategory
	if err := json.Unmarshal([]byte(evil), &bad); err == nil {
		fmt.Printf("  family_id=%d  is_active=%v  version=%d  name=%s\n",
			bad.FamilyID, bad.IsActive, bad.Version, bad.Name)
		fmt.Println("  一个请求体同时改了四件事：换家庭、停用分类、绕过乐观锁、改名")
		fmt.Println("  这就是「共用 struct」的代价 —— 前端能碰到所有它看得见的字段")
	}
	fmt.Println("  对策：CreateReq 里只放 {name, parent_id, type}，其余一律服务端填")

	fmt.Println("\n=== 5. 第三种类型：row（数据库行）===")
	row := categoryRow{ID: "9f1c...", FamilyID: "7a2e...", Name: "餐饮", SortOrder: 10, Version: 2, IsActive: true}
	m2, _ := rowToModel(row)
	fmt.Printf("  row: SortOrder=%d(int32)  →  model: SortOrder=%d(int)\n", row.SortOrder, m2.SortOrder)
	fmt.Printf("  row: ID=%s(string uuid)  →  model: ID=%d\n", row.ID, m2.ID)
	fmt.Println("  uuid→int64、int32→int、string→*string：每次转换都要处理，转坏了就是数据事故")
	fmt.Println("  这也是 model 不能等于 row 的原因")

	fmt.Println("\n=== 6. 该复用什么？该建什么 ===")
	fmt.Println("  ✅ 三个 struct：model.Category / handler.CreateReq / repo.categoryRow")
	fmt.Println("  ✅ 三个纯函数：req.ApplyTo() / rowToModel() / modelToResp()")
	fmt.Println("  ✅ 转换函数必须有测试（它们是最容易出错的地方）")
	fmt.Println("  ❌ 不要为了「少写一个 struct」而合并 —— 那省下 10 行，赔上 10 个 bug")

	fmt.Println("\n=== S2 d7 到此结束 ===")
	fmt.Println("记住一句话：模型按「变化原因」分层。契约变→DTO，表变→row，规则变→model。")
}

package main

import (
	"errors"
	"fmt"
	"net/http"
)

// =====================================================================
// W8 d8：错误码分段落地（tech-plan §6.2）+ 统一错误响应。
//
// 三个必须讲透的点：
//   1) 为什么要有业务码（HTTP 状态码不够用）
//   2) 分段的意义：让「码」本身携带信息，且能机械校验
//   3) error → (code, httpStatus, message) 的翻译只能有一处
// =====================================================================

// ---- 1. 错误码常量。按段分组，段的意义是「这一段归谁管」。----

const (
	CodeOK Code = 0

	// 1001-1010 认证与令牌
	CodeTokenExpired   Code = 1001
	CodeRefreshInvalid Code = 1002
	CodeNoToken        Code = 1003
	CodeTokenMismatch  Code = 1004

	// 3001-3004 家庭与成员
	CodeFamilyNotFound Code = 3001
	CodeNoPermission   Code = 3002
	CodeMemberNotFound Code = 3003
	CodeMemberExited   Code = 3004

	// 4001-4099 业务规则。tech-plan §6.2 只写了两条（4001/4002），
	// 但业务规则会持续增加，所以实际分配一个整段。
	CodeBalanceNotZero  Code = 4001
	CodeArchiveBlocked  Code = 4002
	CodeCategoryStopped Code = 4003
	CodeVersionConflict Code = 4090

	// 5000 服务端错误
	CodeInternal Code = 5000
)

// ---- 2. Code 类型：不给它用裸 int。----
type Code int

// Desc 返回码的稳定描述。**不要**用错误消息本身当判定依据，
// 文案会变、会本地化、会泄露内部实现。
func (c Code) Desc() string {
	switch c {
	case CodeOK:
		return "成功"
	case CodeTokenExpired:
		return "登录已过期，请重新登录"
	case CodeRefreshInvalid:
		return "刷新凭证无效"
	case CodeNoToken:
		return "缺少认证信息"
	case CodeTokenMismatch:
		return "令牌类型错误"
	case CodeFamilyNotFound:
		return "家庭不存在"
	case CodeNoPermission:
		return "权限不足"
	case CodeMemberNotFound:
		return "成员不存在"
	case CodeMemberExited:
		return "成员已退出"
	case CodeBalanceNotZero:
		return "账户余额非 0，不能归档"
	case CodeArchiveBlocked:
		return "该对象被引用，不能归档"
	case CodeCategoryStopped:
		return "分类已停用"
	case CodeVersionConflict:
		return "数据已被他人修改，请刷新后重试"
	case CodeInternal:
		return "服务端错误"
	}
	// 默认分支刻意返回「未定义错误码」而不是「服务端错误」——
	// 忘了给某个码写文案时，前端会立刻看到问题，而不是静默降级成 500。
	return fmt.Sprintf("未定义错误码 %d", int(c))
}

// httpStatusOf 是**唯一**的码→HTTP 映射表。
// 关键设计：**越权与不存在都返 404**，不返 403。
// 因为 403 等于告诉攻击者「东西存在，只是你没权限」，
// 这对多租户系统是信息泄露（能不能探测 id 是有效信息）。
func httpStatusOf(c Code) int {
	switch {
	case c == CodeOK:
		return 200
	case c >= 1001 && c <= 1010:
		return 401 // 认证与令牌
	case c >= 3001 && c <= 3004:
		// 3002 权限不足返 403 是安全的（它不泄露 id 是否存在），
		// 但「按 id 访问别人的数据」一律走 3001 → 404
		if c == CodeNoPermission {
			return 403
		}
		return 404
	case c >= 4001 && c <= 4099:
		return 409 // 业务规则冲突
	case c == CodeInternal:
		return 500
	}
	return 500
}

// ---- 3. AppError：领域错误的标准形态。----

// AppError 同时携带码和一条**安全的**用户消息。
// err 字段存内部原因（日志用），**绝不**发给客户端。
type AppError struct {
	Code Code
	Msg  string
	Err  error // 内部原因，只进日志
}

func (e *AppError) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("[%d] %s (caused by: %v)", e.Code, e.Msg, e.Err)
	}
	return fmt.Sprintf("[%d] %s", e.Code, e.Msg)
}

// Unwrap 让 errors.Is/As 能挖到内部原因（S1 d16）
func (e *AppError) Unwrap() error { return e.Err }

// New 造一个业务错误
func New(c Code, cause error) *AppError {
	return &AppError{Code: c, Msg: c.Desc(), Err: cause}
}

// ---- 4. 哨兵 + %w 包装：repo 的技术错误怎么变成业务码。----

var errRepoNotFound = errors.New("repo: no rows in result set")

// translate 是 error → *AppError 的**唯一**入口。
// handler 只调它，不自己判断 error 是什么。
func translate(err error) *AppError {
	if err == nil {
		return nil
	}
	// 已经被翻译过就直接返回（幂等）
	var ae *AppError
	if errors.As(err, &ae) {
		return ae
	}
	// 底层技术错误 → 归到 500，**并把内部原因留在 Err 里**
	if errors.Is(err, errRepoNotFound) {
		return New(CodeFamilyNotFound, err) // 这个例子里「查不到」= 不存在
	}
	return &AppError{Code: CodeInternal, Msg: CodeInternal.Desc(), Err: err}
}

// ---- 5. 统一响应体 ----

type Envelope struct {
	Code      Code          `json:"code"`
	Message   string        `json:"message"`
	Data      any           `json:"data"`
	RequestID string        `json:"request_id"`
	Errors    []FieldDetail `json:"errors,omitempty"`
}

type FieldDetail struct {
	Field  string `json:"field"`
	Reason string `json:"reason"`
}

// Fail 是 handler 唯一的错误出口。
// 注意它**从不**把 ae.Err 的内容放进响应体。
func Fail(w http.ResponseWriter, ae *AppError, fieldErrs []FieldDetail) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(httpStatusOf(ae.Code))
	_ = writeJSON(w, Envelope{
		Code:      ae.Code,
		Message:   ae.Msg,
		Data:      nil,
		RequestID: "req-001",
		Errors:    fieldErrs,
	})
}

// ---- 6. 用错误码驱动前端行为的两个小例子 ----

// 前端可以这样判断（这是业务码存在的意义）：
//
//	switch (res.code) {
//	  case 1001:     → 清 token，跳登录页
//	  case 4090:     → 弹「数据已更新，是否刷新」
//	  case 4003:     → 提示「分类已停用，请换一个」
//	}
//
// 如果只有 HTTP 状态码，前端只能写：
//
//	if (status === 401) { 清 token }
//	if (status === 409) { ??? }   ← 到底是版本冲突还是余额非 0？
//
// 409 一个状态码对应了 4 种业务含义，前端没法区分。
// 这就是「业务码必须在响应体里，而不只是 HTTP 状态」的原因。

func writeJSON(w http.ResponseWriter, v Envelope) error {
	b, err := marshal(v)
	if err != nil {
		return err
	}
	_, _ = w.Write(b)
	return nil
}

func main() {
	fmt.Println("=== 1. 分段一览：段本身携带信息 ===")
	all := []Code{CodeOK, CodeTokenExpired, CodeRefreshInvalid, CodeNoToken, CodeTokenMismatch,
		CodeFamilyNotFound, CodeNoPermission, CodeMemberNotFound, CodeMemberExited,
		CodeBalanceNotZero, CodeArchiveBlocked, CodeCategoryStopped, CodeVersionConflict, CodeInternal}
	for _, c := range all {
		fmt.Printf("  %d → HTTP %d  %s\n", c, httpStatusOf(c), c.Desc())
	}

	fmt.Println("\n=== 2. 越权返 404 不返 403 ===")
	fmt.Printf("  3001 家庭不存在  → HTTP %d（不告诉调用方「存在但没权限」）\n", httpStatusOf(CodeFamilyNotFound))
	fmt.Printf("  3002 权限不足    → HTTP %d（不涉及具体 id，可安全返回）\n", httpStatusOf(CodeNoPermission))
	fmt.Println("  判据：如果这个码会让攻击者知道「某个 id 存在」，就必须归到 3001 → 404")

	fmt.Println("\n=== 3. error 翻译：一条链走到底 ===")
	// 模拟三层调用：handler → service → repo
	repoErr := fmt.Errorf("查询 category: %w", errRepoNotFound)
	svcErr := fmt.Errorf("svc.Get(42): %w", repoErr)
	ae := translate(svcErr)
	fmt.Printf("  原始 error   : %v\n", svcErr)
	fmt.Printf("  翻译后 code  : %d\n", ae.Code)
	fmt.Printf("  翻译后 msg   : %s\n", ae.Msg)
	fmt.Printf("  内部原因保留 : %v\n", ae.Err)
	fmt.Println("  ↑ Msg 是安全的用户文案；Err 里的内部细节只进日志，不进响应体")

	fmt.Println("\n=== 4. 翻译是幂等的：已翻译的不再翻译 ===")
	ae2 := translate(ae)
	fmt.Printf("  translate(ae) == ae ? %v\n", ae2 == ae)

	fmt.Println("\n=== 5. 未识别的 error → 500，不泄露 ===")
	weird := errors.New("pq: password authentication failed for user \"homecube_app\"")
	ae3 := translate(weird)
	fmt.Printf("  code: %d\n", ae3.Code)
	fmt.Printf("  msg : %s\n", ae3.Msg)
	fmt.Printf("  Err : %v  ← 数据库连接串里的用户名，只有日志能看到\n", ae3.Err)
	fmt.Println("  如果把 Err 直接塞进响应体，攻击者就知道你的库用户名和连接方式")

	fmt.Println("\n=== 6. 完整响应体样例 ===")
	samples := []struct {
		desc string
		ae   *AppError
		fe   []FieldDetail
	}{
		{"版本冲突", New(CodeVersionConflict, errors.New("expected v1 got v2")), nil},
		{"余额非 0", New(CodeBalanceNotZero, nil), nil},
		{"字段校验失败", New(CodeCategoryStopped, nil), []FieldDetail{{"name", "不能为空白"}}},
	}
	for _, s := range samples {
		fmt.Printf("  %s:\n", s.desc)
		fmt.Printf("    HTTP %d  %s\n", httpStatusOf(s.ae.Code),
			render(Envelope{Code: s.ae.Code, Message: s.ae.Msg, RequestID: "req-001", Errors: s.fe}))
	}

	fmt.Println("\n=== 7. 一个容易犯的错：把 409 当成通用业务错误码 ===")
	fmt.Println("  409 Conflict 在 HTTP 语义里只表示「状态冲突」，前端无法据此分支。")
	fmt.Println("  如果你把所有业务失败都塞进 409，前端只能靠 message 字符串匹配：")
	fmt.Println(`    if (msg.includes("余额")) ... else if (msg.includes("版本")) ...`)
	fmt.Println("  这和 S1 d16 里「用 strings.Contains 判 error」是同一个错误，只是换了层。")
	fmt.Println("  正确做法：409 只是 HTTP 层的呈现，**分流靠响应体里的 code**。")

	fmt.Println("\n=== S2 d8 到此结束 ===")
	fmt.Println("一句话：错误码是给程序看的，message 是给人看的，Err 是给运维看的，三者不能混。")
}

// marshal / render：本地实现，避免为了打印引入 encoding/json 之外的东西
func marshal(v Envelope) ([]byte, error) {
	out := fmt.Sprintf(`{"code":%d,"message":%s,"data":null,"request_id":%s`,
		int(v.Code), quote(v.Message), quote(v.RequestID))
	if len(v.Errors) > 0 {
		out += `,"errors":[`
		for i, fe := range v.Errors {
			if i > 0 {
				out += ","
			}
			out += fmt.Sprintf(`{"field":%s,"reason":%s}`, quote(fe.Field), quote(fe.Reason))
		}
		out += `]`
	}
	out += `}`
	return []byte(out), nil
}

func render(v Envelope) string {
	b, _ := marshal(v)
	return string(b)
}

// quote：把字符串转成 JSON 字符串字面量（含转义）。
// 真实项目用 encoding/json.Marshal，这里手写是为了让你看清
// 「手拼 JSON」有多容易漏转义——所以永远别手拼。
func quote(s string) string {
	out := `"`
	for _, r := range s {
		switch r {
		case '"':
			out += `\"`
		case '\\':
			out += `\\`
		case '\n':
			out += `\n`
		default:
			out += string(r)
		}
	}
	return out + `"`
}

package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"
)

// =====================================================================
// W8 d9：配置加载。把 S0 d4 的 getenvOr/mustGetenv 收进 internal/platform/config。
//
// 三个必须讲透的点：
//   1) 为什么不能 os.Getenv 直接读（散落、默认值漂移、测试不可控）
//   2) 必须有的：必填校验 / 类型转换 / 默认值集中一处
//   3) Go 与 JS 的关键差异：Go 里环境变量是 **string**，所有转换都要显式
//      且失败必须显式处理，JS 里 process.env 全是 string|undefined 但没人校验
// =====================================================================

// ---- 1. Config 是配置的**唯一真相**：一个 struct，装所有配置。----

type Config struct {
	Env            string // dev | prod
	HTTPAddr       string
	HTTPTimeout    time.Duration
	ShutdownGrace  time.Duration
	DatabaseURL    string
	DBMaxOpenConns int
	DBMaxIdleConns int
	LogLevel       string
	LogFormatJSON  bool
}

// 校验错误：收集所有问题再一次报出，而不是遇到第一个就退出。
type ValidationErrors []string

func (v ValidationErrors) Error() string {
	return "配置校验失败:\n  - " + strings.Join(v, "\n  - ")
}

// ---- 2. Load：唯一的加载入口。内部顺序固定：读 → 转 → 校验。----

func Load() (*Config, error) {
	cfg := &Config{}

	// ---------- 读字符串 ----------
	// getenv 三态：设了 / 设了但空 / 没设。
	// **「设了但空」和「没设」必须区别对待**：
	// PORT= 是运维的失误，静默用默认值会掩盖问题。
	cfg.Env = getenv("APP_ENV", "dev")
	cfg.HTTPAddr = getenv("HTTP_ADDR", ":8080")
	cfg.DatabaseURL = getenv("DATABASE_URL", "") // 必填，故意不给默认
	cfg.LogLevel = getenv("LOG_LEVEL", "info")
	cfg.LogFormatJSON = getenv("LOG_FORMAT", "text") == "json"

	// ---------- 转数字 ----------
	// Go 里 strconv.Atoi 出错时返回 (0, err)。必须检查 err，
	// 因为「0」本身可能是合法配置，静默用 0 会连不上库。
	var errs ValidationErrors

	timeoutStr := getenv("HTTP_TIMEOUT_MS", "5000")
	timeout, err := parseInt(timeoutStr, "HTTP_TIMEOUT_MS", &errs)
	timeoutOK := err == nil // 解析失败就跳过后续校验，避免「级联报错」
	if timeoutOK {
		cfg.HTTPTimeout = time.Duration(timeout) * time.Millisecond
	}

	graceStr := getenv("SHUTDOWN_GRACE_MS", "10000")
	grace, err := parseInt(graceStr, "SHUTDOWN_GRACE_MS", &errs)
	graceOK := err == nil
	if graceOK {
		cfg.ShutdownGrace = time.Duration(grace) * time.Millisecond
	}

	maxOpen, err := parseInt(getenv("DB_MAX_OPEN_CONNS", "20"), "DB_MAX_OPEN_CONNS", &errs)
	if err == nil {
		cfg.DBMaxOpenConns = maxOpen
	}

	maxIdle, err := parseInt(getenv("DB_MAX_IDLE_CONNS", "5"), "DB_MAX_IDLE_CONNS", &errs)
	if err == nil {
		cfg.DBMaxIdleConns = maxIdle
	}

	// ---------- 转 bool ----------
	// getenvBool 三态返回：值 / 是否被显式设置过。
	// 「显式设为空」要报错，不能当成 false。
	logFmt := getenv("LOG_FORMAT", "text")
	if logFmt == "" {
		errs = append(errs, "LOG_FORMAT 被显式设为空值（想关掉请写 text 或 json）")
	}

	// ---------- 校验 ----------
	if cfg.DatabaseURL == "" {
		errs = append(errs, "DATABASE_URL 是必填项，没有默认值")
	}
	if !strings.HasPrefix(cfg.DatabaseURL, "postgres://") &&
		!strings.HasPrefix(cfg.DatabaseURL, "postgresql://") {
		errs = append(errs, fmt.Sprintf("DATABASE_URL 协议不对（当前 %q），必须是 postgres:// 或 postgresql://",
			redact(cfg.DatabaseURL)))
	}
	if cfg.Env == "prod" && strings.Contains(cfg.DatabaseURL, "sslmode=disable") {
		errs = append(errs, "生产环境不允许 sslmode=disable")
	}
	if timeoutOK && cfg.HTTPTimeout <= 0 {
		errs = append(errs, "HTTP_TIMEOUT_MS 必须 > 0")
	}
	if timeoutOK && graceOK && cfg.ShutdownGrace < cfg.HTTPTimeout {
		errs = append(errs, fmt.Sprintf("SHUTDOWN_GRACE_MS(%d) 必须 >= HTTP_TIMEOUT_MS(%d)，否则请求还没做完进程就退了",
			cfg.ShutdownGrace.Milliseconds(), cfg.HTTPTimeout.Milliseconds()))
	}
	if cfg.DBMaxIdleConns > cfg.DBMaxOpenConns && err == nil {
		errs = append(errs, "DB_MAX_IDLE_CONNS 不能大于 DB_MAX_OPEN_CONNS")
	}

	if len(errs) > 0 {
		return nil, errs
	}
	return cfg, nil
}

// getenv：读环境变量，三态处理。
func getenv(key, def string) string {
	v, ok := os.LookupEnv(key)
	if !ok || v == "" {
		return def
	}
	return v
}

// parseInt：转换并收集错误（不中断，一次报全）。
func parseInt(s, key string, errs *ValidationErrors) (int, error) {
	n, err := strconv.Atoi(s)
	if err != nil {
		*errs = append(*errs, fmt.Sprintf("%s 不是合法整数（当前 %q）", key, s))
		return 0, err
	}
	return n, nil
}

// redact：把连接串里的密码打码，用于日志和报错。
// 这是配置代码的必备动作 —— 否则你把配置打成日志就等于泄露密码。
func redact(dsn string) string {
	// postgres://user:password@host:5432/db?sslmode=disable
	i := strings.Index(dsn, "://")
	if i < 0 {
		return dsn
	}
	rest := dsn[i+3:]
	at := strings.Index(rest, "@")
	if at < 0 {
		return dsn
	}
	userinfo := rest[:at]
	colon := strings.Index(userinfo, ":")
	if colon < 0 {
		return dsn
	}
	return dsn[:i+3] + userinfo[:colon] + ":***" + rest[at:]
}

// ---- 3. mustLoad：给 main 用。加载失败就直接退出，不带病启动。----
// 注意命名：must 前缀在 Go 里表示「失败会 panic」，调用者一眼知道。
func mustLoad() *Config { //nolint:unused // 真实 main.go 里第一行就是它
	cfg, err := Load()
	if err != nil {
		fmt.Fprintln(os.Stderr, "配置有问题，服务拒绝启动：")
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	return cfg
}

func show(label string, cfg *Config, err error) {
	fmt.Printf("--- %s ---\n", label)
	if err != nil {
		fmt.Printf("  ❌ %v\n\n", err)
		return
	}
	fmt.Printf("  ✅ 加载成功\n")
	fmt.Printf("     Env=%s  HTTPAddr=%s\n", cfg.Env, cfg.HTTPAddr)
	fmt.Printf("     HTTPTimeout=%v  ShutdownGrace=%v\n", cfg.HTTPTimeout, cfg.ShutdownGrace)
	fmt.Printf("     DBMaxOpen=%d  DBMaxIdle=%d\n", cfg.DBMaxOpenConns, cfg.DBMaxIdleConns)
	fmt.Printf("     LogLevel=%s  LogJSON=%v\n", cfg.LogLevel, cfg.LogFormatJSON)
	fmt.Printf("     DatabaseURL=%s  ← 已打码\n\n", redact(cfg.DatabaseURL))
}

func set(kv ...string) { // 小helper：批量设环境变量
	for i := 0; i < len(kv); i += 2 {
		if kv[i+1] == "" {
			_ = os.Unsetenv(kv[i])
			continue
		}
		_ = os.Setenv(kv[i], kv[i+1])
	}
}

func main() {
	// 场景1：什么都不设 → 报 DATABASE_URL 必填
	set("DATABASE_URL", "", "HTTP_TIMEOUT_MS", "", "SHUTDOWN_GRACE_MS", "",
		"DB_MAX_OPEN_CONNS", "", "DB_MAX_IDLE_CONNS", "", "LOG_FORMAT", "")
	cfg, err := Load()
	show("场景1: 全新环境（无任何环境变量）", cfg, err)

	// 场景2：配全了，正常加载
	set("DATABASE_URL", "postgres://homecube_app:s3cr3t@db:5432/homecube?sslmode=disable",
		"APP_ENV", "dev", "HTTP_ADDR", ":8080", "HTTP_TIMEOUT_MS", "5000",
		"SHUTDOWN_GRACE_MS", "10000", "DB_MAX_OPEN_CONNS", "20", "DB_MAX_IDLE_CONNS", "5")
	cfg, err = Load()
	show("场景2: 开发环境配置齐全", cfg, err)

	// 场景3：多个错误一次性报出（不逐个试错）
	set("HTTP_TIMEOUT_MS", "abc", "SHUTDOWN_GRACE_MS", "10000", "DB_MAX_OPEN_CONNS", "20", "DB_MAX_IDLE_CONNS", "50")
	cfg, err = Load()
	show("场景3: 多个配置同时错（一次报全）", cfg, err)

	// 场景4：超时与宽限期矛盾 —— 这条规则救过很多人
	set("HTTP_TIMEOUT_MS", "10000", "SHUTDOWN_GRACE_MS", "3000", "DB_MAX_IDLE_CONNS", "5")
	cfg, err = Load()
	show("场景4: 宽限期 < 请求超时", cfg, err)

	// 场景5：生产环境用 sslmode=disable 被拦
	set("APP_ENV", "prod", "HTTP_TIMEOUT_MS", "5000", "SHUTDOWN_GRACE_MS", "10000",
		"DB_MAX_IDLE_CONNS", "5")
	cfg, err = Load()
	show("场景5: 生产环境 sslmode=disable", cfg, err)

	// 场景6：全部合法的生产配置
	set("DATABASE_URL", "postgres://homecube_app:s3cr3t@db.internal:5432/homecube?sslmode=require")
	cfg, err = Load()
	show("场景6: 生产配置合法（sslmode=require）", cfg, err)

	// 场景7：默认值本身也有讲究
	set("APP_ENV", "", "DATABASE_URL", "", "HTTP_ADDR", "", "LOG_LEVEL", "")
	set("DATABASE_URL", "postgresql://u:p@h:5432/d?sslmode=require")
	cfg, err = Load()
	show("场景7: 只设必填项，其余全走默认值", cfg, err)
	if err == nil {
		fmt.Println("  注意这里：APP_ENV 没设 → 走默认 'dev'（不是空串）")
		fmt.Println("  这就是 getenv 的三态处理在起作用")
	}

	fmt.Println("=== 为什么必须收进一个 struct，而不是到处 os.Getenv ===")
	fmt.Println("  1) 只有一个地方知道默认值是什么 —— 改默认值只改一处")
	fmt.Println("  2) 配置错误在启动时一次性报全，而不是运行时随机爆")
	fmt.Println("  3) 测试可以构造 Config{} 直接注入，不用改环境变量（Go 里 os.Setenv 是全局的，并发测试会互相污染）")
	fmt.Println("  4) main 拿到的是普通 struct，可以直接传给任何层；不需要到处传 map")
	fmt.Println()
	fmt.Println("=== Go 与 JS 的关键差异 ===")
	fmt.Println("  JS: const port = process.env.PORT  → 永远是 string，'8080' === 8080 为 false")
	fmt.Println("      前端随便 Number() 一下，出错就是 NaN，还很难查")
	fmt.Println("  Go: os.Getenv 只给 string。所有类型转换必须显式 strconv.Atoi，")
	fmt.Println("      而且 Go 强制你检查 error（不检查 vet 会报警），这正好挡住了配置事故")
	fmt.Println("  这是 Go 在这个场景下的真实优势：不是「更安全」，是「编译器逼你处理」")

	fmt.Println("\n=== S2 d9 到此结束 ===")
	fmt.Println("下一步（d10）：配置里的 ShutdownGrace 到底有什么用 —— 服务怎么优雅关闭。")
	_ = mustLoad
}

package main

import (
	"context"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

// =====================================================================
// W8 d10：优雅关闭（graceful shutdown）。
//
// 问题：收到 SIGTERM 后如果直接 os.Exit(1) 会怎样？
//   → 在途请求被硬切 → 用户看到「请求失败」→ 前端重试 → 可能重复扣款
//   → 数据库连接池没关 → Postgres 侧残留 backend 进程
//
// 解法三步（顺序不能换）：
//   1. 停止接受新连接（关 listener）
//   2. 等在途请求做完（bounded wait）
//   3. 关闭下游资源（DB 连接池、消息总线）
// =====================================================================

// ---- 一个能观察「在途请求」的服务器 ----

type Server struct {
	srv *http.Server

	// inflight 记录在途请求数。用 atomic 而不是 mutex，
	// 因为读它的频率（每毫秒）远高于写。
	inflight atomic.Int64

	// completed 累计完成数，用于验证「请求真的做完了」
	completed atomic.Int64

	// onShutdownStart 在 Shutdown 开始时被调用
	onShutdownStart hook

	mu   sync.Mutex
	logs []string
}

func (s *Server) log(format string, args ...any) {
	line := fmt.Sprintf(format, args...)
	s.mu.Lock()
	s.logs = append(s.logs, line)
	s.mu.Unlock()
}

func (s *Server) Logs() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]string, len(s.logs))
	copy(out, s.logs)
	return out
}

func NewServer(addr string, work time.Duration) *Server {
	s := &Server{}
	mux := http.NewServeMux()

	mux.HandleFunc("/api/homeos/slow", func(w http.ResponseWriter, r *http.Request) {
		s.inflight.Add(1)
		defer s.inflight.Add(-1)

		id := r.URL.Query().Get("id")
		// 模拟真实工作：查库 + 写库
		time.Sleep(work)

		s.completed.Add(1)
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintf(w, `{"code":0,"data":{"id":%s,"status":"completed"}}`, id)
	})

	mux.HandleFunc("/api/homeos/fast", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"code":0,"data":{"fast":true}}`))
	})

	// /healthz 在关闭开始后立刻返回 503，
	// 这样负载均衡器/K8s 会把流量摘走（这一步很多人漏）。
	var shuttingDown atomic.Bool
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		if shuttingDown.Load() {
			w.WriteHeader(http.StatusServiceUnavailable)
			_, _ = w.Write([]byte(`{"code":0,"data":{"status":"shutting_down"}}`))
			return
		}
		_, _ = w.Write([]byte(`{"code":0,"data":{"status":"up"}}`))
	})

	s.srv = &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second, // 必须设，否则 slowloris 能把连接占死
	}
	s.onShutdownStart = func() { shuttingDown.Store(true) }
	return s
}

// onShutdownStart：Shutdown 开始时回调，用来把 healthz 切成 503
type hook func()

// ListenAndServe 在后台跑
func (s *Server) Start() error {
	ln, err := net.Listen("tcp", s.srv.Addr)
	if err != nil {
		return err
	}
	go func() { _ = s.srv.Serve(ln) }()
	s.log("listening on %s", s.srv.Addr)
	return nil
}

// Shutdown 是标准库提供的优雅关闭。它内部做的事：
//  1. 关 listener（不再接受新连接）
//  2. 轮询直到 inFlight == 0
//  3. 超时则强制 Close
//
// ctx 给了宽限期：超时后会返回 context.DeadlineExceeded，
// 此时**必须**调 s.srv.Close() 强制掐断剩余连接。
func (s *Server) Shutdown(ctx context.Context) error {
	s.onShutdownStart()
	s.log("收到关闭信号，开始优雅关闭（宽限期 %s）", deadlineOf(ctx))
	err := s.srv.Shutdown(ctx)
	if err != nil {
		s.log("宽限期内没关完，强制关闭: %v", err)
		_ = s.srv.Close()
	} else {
		s.log("在途请求已全部完成，干净退出")
	}
	s.log("本次关闭共完成 %d 个请求", s.completed.Load())
	return err
}

func deadlineOf(ctx context.Context) string {
	if dl, ok := ctx.Deadline(); ok {
		return time.Until(dl).Round(time.Millisecond).String()
	}
	return "无期限"
}

// =====================================================================
// main 演示：完整的服务生命周期
// =====================================================================

func main() {
	s := NewServer("127.0.0.1:18099", 400*time.Millisecond)
	if err := s.Start(); err != nil {
		fmt.Println("启动失败:", err)
		return
	}
	base := "http://127.0.0.1:18099"

	// ---- 信号监听：真实项目就是这么写的 ----
	// signal.NotifyContext 把「收到 SIGINT/SIGTERM」变成一个可关闭的 context。
	// 这是 Go 1.16+ 的标准做法，比 channel + goroutine 干净。
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	fmt.Println("=== 服务已启动 ===")
	fmt.Printf("  %s/healthz → %s\n", base, get(base+"/healthz"))

	// ---- 发起 3 个慢请求（模拟在途请求），不等它们完成 ----
	fmt.Println("\n=== 发起 3 个在途请求（每个耗时 400ms）===")
	var wg sync.WaitGroup
	results := make([]string, 3)
	for i := 1; i <= 3; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			results[n-1] = fmt.Sprintf("  req-%d %s", n, get(fmt.Sprintf("%s/api/homeos/slow?id=%d", base, n)))
		}(i)
	}

	// 等 100ms，确保三个请求都已经进入 handler（inflight = 3）
	time.Sleep(100 * time.Millisecond)
	fmt.Printf("  此刻在途请求数 = %d\n", s.inflight.Load())
	fmt.Printf("  %s/healthz → %s\n", base, get(base+"/healthz"))
	fmt.Println("  （注意：此时请求还在处理中，inflight = 3）")

	// ---- 触发关闭 ----
	fmt.Println("\n=== 触发 SIGTERM（等价于 Ctrl+C 或 docker stop）===")
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	// 真正给自己发一个 SIGTERM，走完整的信号路径。
	// 这比手动 cancel() 更真实：docker stop、Ctrl+C 走的都是这条路径。
	// 注意千万别用 NotifyContext 返回的 stop() 来「模拟信号」——
	// stop() 的作用是**注销**信号监听，注销后 SIGTERM 恢复默认行为＝直接杀进程。
	shutdownDone := make(chan error, 1)
	go func() {
		<-ctx.Done() // 收到 SIGTERM 后 ctx 被取消
		shutdownDone <- s.Shutdown(shutdownCtx)
	}()

	if err := syscall.Kill(os.Getpid(), syscall.SIGTERM); err != nil {
		fmt.Println("  发信号失败:", err)
	}

	wg.Wait() // ① 等三个在途请求完成
	// ② 等优雅关闭真正结束 —— 这一步不能省！
	// 省了的话 main 返回 → 进程立刻退出 → 关闭日志只写一半、
	// 下游资源（DB 连接池）根本没关。
	if err := <-shutdownDone; err != nil {
		fmt.Printf("  Shutdown 返回: %v（宽限期内没关完，已强制关闭）\n", err)
	} else {
		fmt.Println("  Shutdown 返回: nil（干净退出）")
	}

	fmt.Println("\n=== 三个在途请求全部完成，没有一个被切断 ===")
	for _, r := range results {
		fmt.Println(r)
	}
	fmt.Printf("  完成数 = %d，在途 = %d  ← 关键：完成数=3 说明没有一个请求被强杀\n", s.completed.Load(), s.inflight.Load())

	// ---- 关闭后：新请求必须失败 ----
	fmt.Println("\n=== 关闭后再发请求 ===")
	_, err := http.Get(base + "/api/homeos/fast")
	if err != nil {
		fmt.Printf("  ✅ 连接被拒绝（这是对的）: %v\n", err)
	} else {
		fmt.Println("  ❌ 还能连上，说明 listener 没关")
	}

	fmt.Println("\n=== 关闭日志 ===")
	for _, l := range s.Logs() {
		fmt.Println("  " + l)
	}

	fmt.Println("\n=== 关键知识点 ===")
	fmt.Println("  1) 顺序不能换：先 healthz 报 503（让 LB 摘流量）→ 再 Shutdown → 最后关 DB")
	fmt.Println("  2) Shutdown(ctx) 会等在途请求做完，但 ctx 超时就强杀 —— 所以宽限期必须 >= 最长请求耗时")
	fmt.Println("  3) ReadHeaderTimeout 必须设，否则攻击者用慢速请求就能占住连接不放")
	fmt.Println("  4) signal.NotifyContext + defer stop() 是标准写法，不要手写 channel")
	fmt.Println("  5) 关停期间仍要能响应 /healthz（返回 503），否则 LB 一直往这里打请求")

	fmt.Println("\n=== 对照：Node.js 是怎么做的 ===")
	fmt.Println("  JS: process.on('SIGTERM', () => server.close(() => process.exit(0)))")
	fmt.Println("  Node 的 server.close() 行为与 Go 的 Shutdown 几乎一致（都等在途请求）")
	fmt.Println("  差别在两处：")
	fmt.Println("    a) Node 里你不主动 process.exit，事件循环空了也会自己退出；")
	fmt.Println("       Go 里主 goroutine 一结束整个进程就死，所以必须 select{} 或等 Shutdown 返回")
	fmt.Println("    b) Node 有 uncaughtException 会让进程直接挂掉；Go 的 panic 默认也是挂进程，")
	fmt.Println("       所以两边都必须写 recovery（d3 已经写过）")

	fmt.Println("\n=== S2 d10 到此结束 ===")
	fmt.Println("下一步（d11）：把所有路由摊开看，验证「必须分域」这条硬约束。")

}

// get：一个极简的 GET 客户端，打印状态码和 body。
// 注意它设了 Timeout —— 真实项目里所有出网调用都必须有超时（S1 d21/d22 讲过）。
func get(url string) string {
	client := &http.Client{Timeout: 5 * time.Second}
	resp, err := client.Get(url)
	if err != nil {
		return "ERR " + err.Error()
	}
	defer resp.Body.Close()
	b, err := io.ReadAll(resp.Body)
	if err != nil {
		return fmt.Sprintf("HTTP %d (读 body 失败: %v)", resp.StatusCode, err)
	}
	return fmt.Sprintf("HTTP %d  %s", resp.StatusCode, strings.TrimSpace(string(b)))
}

package main

import (
	"fmt"
	"sort"
	"strings"
)

// =====================================================================
// W8 d11：路由必须分域（tech-plan §6.1 第 1 条 / §10.3 第 5 条）
// 以及 CI 门禁第 4 条的预演。
//
// 核心问题：分域不是「风格问题」，它是**故障隔离**的手段。
// 如果 /api/finance/* 和 /api/homeos/* 混在一个服务里，
// finance 的一条慢查询会拖垮整个 HomeOS。
//
// 今天做的事：把「纪律」变成「可执行的检查」。
// =====================================================================

// ---- 1. 用一份「路由登记表」模拟真实的 OpenAPI 清单 ----

type Route struct {
	Method  string
	Path    string
	Service string // 声称由哪个服务提供
	Handler string
	Auth    bool
}

// GoodRoutes 是「正确」的 6 条：全部在 /api/homeos/ 下
var GoodRoutes = []Route{
	{"GET", "/healthz", "svc-homeos", "healthz", false},
	{"POST", "/api/homeos/categories", "svc-homeos", "CreateCategory", true},
	{"GET", "/api/homeos/categories", "svc-homeos", "ListCategories", true},
	{"GET", "/api/homeos/categories/:id", "svc-homeos", "GetCategory", true},
	{"PUT", "/api/homeos/categories/:id", "svc-homeos", "UpdateCategory", true},
	{"POST", "/api/homeos/categories/:id/stop", "svc-homeos", "StopCategory", true},
}

// BadRoutes 复现三种真实翻车形态（这些都真的发生过）
var BadRoutes = []Route{
	// 翻车1：根路径业务接口 —— Nginx 无法按前缀分流，
	// 因为它可能就是某个服务的根
	{"GET", "/categories", "svc-homeos", "ListCategories", true},
	// 翻车2：写错 code —— 拼成了 /api/homeos_/ 或漏了 code
	{"GET", "/api/categories", "svc-homeos", "ListCategories", true},
	// 翻车3：把别域的接口写在本服务里 —— 归属门禁会拦，但路由门禁也该拦
	{"GET", "/api/finance/categories", "svc-homeos", "ListFinanceCategories", true},
}

// ---- 2. 允许的运维路径白名单：根路径只放这些 ----

var AllowedRootPaths = map[string]string{
	"/healthz": "GET",
	"/readyz":  "GET",
	"/metrics": "GET",
	"/livez":   "GET",
}

// ---- 3. 三条服务 code（tech-plan §4：七类命名同源）----

var KnownCodes = map[string]bool{
	"homeos":   true,
	"calendar": true,
	"finance":  true,
}

// ---- 4. 门禁实现 ----

type Violation struct {
	Rule    string
	Method  string
	Path    string
	Message string
}

// CheckRouteDomain 实现「门禁 4-1：路由全在 /api/{code}/ 下」
func CheckRouteDomain(routes []Route, selfCode string) []Violation {
	var bad []Violation
	for _, r := range routes {
		switch {
		// 规则1：根路径必须在白名单里
		case !strings.HasPrefix(r.Path, "/api/"):
			if allowed, ok := AllowedRootPaths[r.Path]; !ok || allowed != r.Method {
				bad = append(bad, Violation{
					Rule: "4-1 分域", Method: r.Method, Path: r.Path,
					Message: fmt.Sprintf("根路径 %s 不在运维白名单里。Nginx 靠 /api/{code}/ 前缀分流，"+
						"根路径接口无法归类", r.Path),
				})
			}

		// 规则2：/api/ 后面必须紧跟一个已知 code
		case !hasKnownCode(r.Path):
			seg := segmentAfterAPI(r.Path)
			hint := ""
			if seg == "" {
				hint = "（/api/ 后面没有 code 段）"
			} else if strings.HasSuffix(seg, "_") || strings.HasSuffix(seg, "-") {
				hint = "（code 后面多了分隔符，应为 /api/{code}/xxx）"
			} else if !KnownCodes[seg] {
				hint = fmt.Sprintf("（未知 code %q，已知：homeos / calendar / finance）", seg)
			}
			bad = append(bad, Violation{
				Rule: "4-1 分域", Method: r.Method, Path: r.Path,
				Message: fmt.Sprintf("路径 %s 的域段不合法 %s", r.Path, hint),
			})

		// 规则3：本服务只能声明自己的 code
		case !strings.HasPrefix(r.Path, "/api/"+selfCode+"/"):
			other := segmentAfterAPI(r.Path)
			bad = append(bad, Violation{
				Rule: "4-1 归属", Method: r.Method, Path: r.Path,
				Message: fmt.Sprintf("svc-%s 里出现了 /api/%s/* 的路由，"+
					"要么接口放错了服务，要么需要先登记", selfCode, other),
			})
		}
	}
	return bad
}

func segmentAfterAPI(p string) string {
	trimmed := strings.TrimPrefix(p, "/api/")
	if i := strings.Index(trimmed, "/"); i >= 0 {
		return trimmed[:i]
	}
	return trimmed
}

func hasKnownCode(p string) bool {
	seg := segmentAfterAPI(p)
	return seg != "" && KnownCodes[seg]
}

// CheckAuth 顺带演示门禁 4 的另一条：写接口必须鉴权
func CheckAuth(routes []Route) []Violation {
	var bad []Violation
	for _, r := range routes {
		isWrite := r.Method != "GET" && r.Method != "HEAD"
		if isWrite && !r.Auth {
			bad = append(bad, Violation{
				Rule: "4-2 鉴权", Method: r.Method, Path: r.Path,
				Message: "写接口没有声明鉴权",
			})
		}
	}
	return bad
}

// ---- 5. 报告 ----

func report(title string, routes []Route, selfCode string) {
	fmt.Printf("=== %s ===\n", title)
	fmt.Printf("  检查 %d 条路由，服务 code = %s\n", len(routes), selfCode)

	domainBad := CheckRouteDomain(routes, selfCode)
	authBad := CheckAuth(routes)

	// 排序保证输出稳定
	sort.Slice(domainBad, func(i, j int) bool {
		if domainBad[i].Rule != domainBad[j].Rule {
			return domainBad[i].Rule < domainBad[j].Rule
		}
		return domainBad[i].Path < domainBad[j].Path
	})

	if len(domainBad) == 0 && len(authBad) == 0 {
		fmt.Println("  ✅ 全部通过")
	} else {
		for _, v := range append(domainBad, authBad...) {
			fmt.Printf("  ❌ [%s] %s %s\n", v.Rule, v.Method, v.Path)
			fmt.Printf("     %s\n", v.Message)
		}
	}
	fmt.Println()
}

func main() {
	fmt.Println("### 为什么要分域？三个理由（不是「好看」）")
	fmt.Println()
	fmt.Println("① 故障隔离：Nginx 按 /api/{code}/ 前缀转发，finance 慢查询不会拖垮 homeos")
	fmt.Println("② 归属可查：看到 /api/finance/xxx 就知道该找谁，不用全局搜索")
	fmt.Println("③ 契约治理：每个域有独立的 OpenAPI 和事件目录，能独立版本化")
	fmt.Println("   tech-plan §4 的「七类命名同源」：code → 服务/schema/路由/事件前缀/表前缀/分包/迁移序列")
	fmt.Println()

	report("正确的 6 条路由（svc-homeos）", GoodRoutes, "homeos")
	report("三种翻车写法", BadRoutes, "homeos")

	fmt.Println("=== 如果不检查会怎样：Nginx 分流表 ===")
	fmt.Println("  nginx.conf 只能这么写：")
	fmt.Println("    location /api/homeos/  { proxy_pass http://svc-homeos:8080; }")
	fmt.Println("    location /api/finance/ { proxy_pass http://svc-finance:8080; }")
	fmt.Println("    location /             { proxy_pass http://svc-homeos:8080; }  ← 兜底")
	fmt.Println()
	fmt.Println("  于是：")
	for _, r := range BadRoutes {
		switch {
		case r.Path == "/categories":
			fmt.Printf("    %s %-32s → 落到兜底规则，被当成 homeos 的接口\n", r.Method, r.Path)
			fmt.Println("       后果：finance 服务里明明有这条路由，nginx 却把它转给了 homeos")
		case r.Path == "/api/categories":
			fmt.Printf("    %s %-32s → 落到兜底规则\n", r.Method, r.Path)
			fmt.Println("       后果：网关无法按域分流，这个接口等于没有归属")
		case r.Path == "/api/finance/categories":
			fmt.Printf("    %s %-32s → 转给了 svc-finance\n", r.Method, r.Path)
			fmt.Println("       后果：homeos 的代码里出现了 finance 的路由，责任边界糊了")
		}
	}
	fmt.Println()

	fmt.Println("=== 门禁怎么落地到 CI ===")
	fmt.Println("  1) 本卡的逻辑用 Go 写成一个 cmd/routecheck，跑 `go run ./cmd/routecheck`")
	fmt.Println("     从真实的路由注册表（BuildRouter().Routes()）读，不手写清单 —— 手写清单会漂移")
	fmt.Println("  2) 有违规就 os.Exit(1)，CI 立刻红")
	fmt.Println("  3) 更轻的做法：grep 检查源码里的注册调用")
	fmt.Println("     grep -rnE '\\.(GET|POST|PUT|DELETE|PATCH)\\(\"/(?!api/)' internal/ --include='*.go'")
	fmt.Println("     （Go 的 regexp 不支持 (?!)  lookahead，所以实际会用 ripgrep -P 或者写个小工具）")
	fmt.Println("  4) OpenAPI 文件也要跑一遍：yaml 里的 paths 必须与代码一致（契约门禁）")

	fmt.Println("\n=== 一个容易被忽略的细节 ===")
	fmt.Println("  /healthz 这类根路径接口是**例外**，但必须是有限白名单。")
	fmt.Println("  如果不设白名单，「根路径不许业务接口」就变成了一句口头纪律。")
	fmt.Println("  白名单本身也该进代码常量，让它可review、可diff、可测。")

	fmt.Println("\n=== Go 与 JS 的差异 ===")
	fmt.Println("  JS 里路由常常写在各处：app.get(...)、router.post(...)、甚至配置文件里，")
	fmt.Println("  没有一个统一的「路由表」可以枚举，所以这种门禁很难写。")
	fmt.Println("  Go 里所有路由都必须通过 engine.Group / engine.Handle 注册，")
	fmt.Println("  而 engine.Routes() 能把**已注册的全部路由**枚举出来 —— 这让门禁写得出来。")
	fmt.Println("  换句话说：Go 的「集中注册」不只是风格，它让「可审计」成为可能。")

	fmt.Println("\n=== S2 d11 到此结束 ===")
	fmt.Println("下一步（d12）：把 S2 的全部判据写成 scripts/s2-check.sh，跑一遍看还差什么。")
}

