// ---- 断言收集器 ----

type Check struct {
	Name   string
	Detail string
	Pass   bool
	Reason string
}

type Report struct {
	Title   string
	Checks  []Check
	Skipped int
}

func (r *Report) add(name, detail string, pass bool, reason string) {
	r.Checks = append(r.Checks, Check{Name: name, Detail: detail, Pass: pass, Reason: reason})
}

func (r *Report) Print() int {
	pass := 0
	fail := 0
	fmt.Printf("════════ %s ════════\n", r.Title)
	for _, c := range r.Checks {
		if c.Pass {
			pass++
			fmt.Printf("  ✅ %-38s %s\n", c.Name, c.Detail)
		} else {
			fail++
			fmt.Printf("  ❌ %-38s %s\n", c.Name, c.Detail)
			if c.Reason != "" {
				fmt.Printf("       ↳ %s\n", c.Reason)
			}
		}
	}
	fmt.Printf("────────────────────────────────────────\n")
	fmt.Printf("  通过 %d 条，失败 %d 条", pass, fail)
	if r.Skipped > 0 {
		fmt.Printf("，跳过 %d 条", r.Skipped)
	}
	fmt.Println()
	if fail > 0 {
		fmt.Println("  结论：S2 未通过。判据不达标就顺延，不要压缩完整度（纪律 #2）")
	} else {
		fmt.Println("  结论：S2 通过，可以进 S3")
	}
	return fail
}

// ---- 模拟「跑一个命令」的结果。真实实现里是 exec.Command ----
// 为了让今天的输出完全可复现，这里不真跑命令，而是用已知结果表。

type cmdResult struct {
	out  string
	code int
}

// fakeRun 是真实项目里 exec.Command 的替身。
// 真实写法：
//
//	out, err := exec.Command("go", "vet", "./...").CombinedOutput()
//
// 今天用假结果，因为本机的 lab/ 目录是教学用的，不在真实仓库里。
func fakeRun(args string) cmdResult {
	switch {
	case strings.Contains(args, "go build ./..."):
		return cmdResult{"", 0}
	case strings.Contains(args, "go vet ./..."):
		return cmdResult{"", 0}
	case strings.Contains(args, "-race"):
		return cmdResult{"ok  \thomecube/internal/homeos/service\t0.031s\nok  \thomecube/internal/homeos/handler\t0.018s", 0}
	case strings.Contains(args, "routecheck"):
		return cmdResult{"✅ 12 条路由全部在 /api/homeos/ 下", 0}
	}
	return cmdResult{"未知命令", 1}
}

