// ---- 对比：bash 版s2-check.sh 长什么样 ----

const s2CheckSh = `#!/usr/bin/env bash
# S2 阶段自查脚本。照s0-check.sh 的风格写。
set -uo pipefail
cd "$(dirname "$0")/.." || exit 1

PASS=0; FAIL=0
check() {
  local desc="$1"; shift
  if out=$("$@" 2>&1); then
    printf '  ✅ %s\n' "$desc"; PASS=$((PASS+1))
  else
    printf '  ❌ %s\n' "$desc"
    printf '     ↳ %s\n' "$(echo "$out" | head -2 | tr '\n' '|')"
    FAIL=$((FAIL+1))
  fi
}
checkgrep() {
  local desc="$1" pattern="$2" path="$3"
  if grep -rqE "$pattern" "$path" 2>/dev/null; then
    printf '  ✅ %s\n' "$desc"; PASS=$((PASS+1))
  else
    printf '  ❌ %s\n' "$desc"
    printf '     ↳ 在 %s 里找不到 /%s/\n' "$path" "$pattern"
    FAIL=$((FAIL+1))
  fi
}

echo "════════ S2 阶段自查 ════════"

# ---- 构建与静态检查 ----
check "go build 通过"          go build ./...
check "go vet 干净"            go vet ./...
check "go test -race 全绿"     go test -race ./...

# ---- 四层目录齐全（判据第1 条）----
for d in handler service repo model; do
  if [ -d "internal/homeos/$d" ]; then
    printf '  ✅ internal/homeos/%s 存在\n' "$d"; PASS=$((PASS+1))
  else
    printf '  ❌ internal/homeos/%s 不存在\n' "$d"; FAIL=$((FAIL+1))
  fi
done

# ---- 统一响应体（判据第 2 条）----
checkgrep "platform/response 存在统一响应体" \
  'type Envelope struct' internal/platform/response/
checkgrep "响应体含request_id" \
  'request_id' internal/platform/response/

# ---- 依赖方向：handler 不得 import repo（门禁 4-4）----
if grep -rq 'internal/homeos/repo' internal/homeos/handler/ 2>/dev/null; then
  printf '  ❌ handler 里出现了 repo 的 import（跨层调用）\n'; FAIL=$((FAIL+1))
else
  printf '  ✅ handler 未依赖 repo\n'; PASS=$((PASS+1))
fi

# ---- 路由分域（门禁 4-1）----
check "路由门禁自检"            go run ./cmd/routecheck

# ---- 错误码分段完整（判据第 3 条）----
for code in 0 1001 1002 3001 3002 4001 4002 5000; do
  if grep -rqE "(Code[A-Za-z]+ +Code = $code|= $code$)" internal/platform/response/ 2>/dev/null; then
    printf '  ✅ 错误码 %s 已定义\n' "$code"; PASS=$((PASS+1))
  else
    printf '  ❌ 错误码 %s 未定义\n' "$code"; FAIL=$((FAIL+1))
  fi
done

# ---- 配置与优雅关闭（判据第 4 条）----
checkgrep "配置集中在一个 Config"    'type Config struct'   internal/platform/config/
checkgrep "优雅关闭用 signal"        'signal.NotifyContext' cmd/
checkgrep "Shutdown 有宽限期"        'context.WithTimeout'  cmd/

echo "────────────────────────────────────────"
echo "  通过 $PASS 条，失败 $FAIL 条"
[ "$FAIL" -eq 0 ] || exit 1
`

func main() {
	r := S2Report()
	fail := r.Print()

	fmt.Println()
	fmt.Println("### 顺带验证一下命令执行（bash 版s2-check.sh 的依赖）")
	for _, cmd := range []string{
		"go build ./...",
		"go vet ./...",
		"go test -race ./...",
		"go run ./cmd/routecheck",
	} {
		res := fakeRun(cmd)
		status := "✅"
		if res.code != 0 {
			status = "❌"
		}
		fmt.Printf("  %s $ %s\n", status, cmd)
		if res.out != "" {
			for _, line := range strings.Split(strings.TrimRight(res.out, "\n"), "\n") {
				fmt.Printf("       %s\n", line)
			}
		}
	}

	fmt.Println()
	fmt.Println("### 门禁脚本里最容易写错的三处")
	fmt.Println("  1) set -uo pipefail 后，命令失败不会自动退出 —— 必须靠 check() 累积 FAIL 再 exit 1")
	fmt.Println("     只写 set -e 是不够的：它在 check 内部的 if 里不会触发")
	fmt.Println("  2) grep -q 用在 if 里是对的，但写成 grep ... || true 就把失败吞掉了")
	fmt.Println("  3) 退出码必须是 1 而不是 0，否则 CI 认为通过（这是最常见的「假绿」）")

	fmt.Println("\n### S2 的三条通过判据（learning-plan §四）")
	fmt.Println("  ① 徒手写一个带分层与中间件的 CRUD（内存存储即可）")
	fmt.Println("     → d6 的 5 条接口 × 3 层，存储是 memRepo")
	fmt.Println("  ② 讲清：handler / service / repo 各自负责什么，")
	fmt.Println("            为什么 DTO 和领域模型要分开")
	fmt.Println("     → d4 讲了职责，d7 讲了三个硬理由（敏感字段/白名单构造/命名演进）")
	fmt.Println("  ③ 看出：自己的代码里有没有跨层调用")
	fmt.Println("     → d6 的 checkArchitecture + 今天的 grep 门禁")

	fmt.Println("\n" + strings.Repeat("═", 60))
	fmt.Println("### 费曼复盘：不看资料，回答这三个问题")
	fmt.Println()
	fmt.Println("【Q1】一个请求从进入到返回，经过了哪几层？每层各做了什么？")
	fmt.Println("  参考答案（要能自己说出来才算过）：")
	fmt.Println("    中间件链（request_id → recovery → 日志）")
	fmt.Println("      → gin 路由匹配")
	fmt.Println("        → handler：解析 body、校验、调 service、组装响应")
	fmt.Println("          → service：业务规则判定、跨表编排（事务边界在这层）")
	fmt.Println("            → repo：单表 CRUD、拼 WHERE 条件")
	fmt.Println("              → 存储（今天是 map，S3 换 Postgres）")
	fmt.Println("    回程：repo → service → handler 组装 Envelope → 中间件写日志")
	fmt.Println()
	fmt.Println("【Q2】为什么 DTO 和领域模型要分开？说三个理由。")
	fmt.Println("  参考答案：")
	fmt.Println("    ① 敏感字段：model 有 internal_note 等内部字段，共用就泄露给前端")
	fmt.Println("    ② 写入白名单：共用 struct 的话前端能传 family_id / is_active / version，")
	fmt.Println("       等于把多租户隔离和乐观锁的门钥匙交给前端")
	fmt.Println("    ③ 变化原因不同：契约变（前端改需求）→ DTO；表变（DB 改类型）→ row；")
	fmt.Println("       业务规则变 → model。三者演进节奏不同，共用一个 struct 就必须同时改")
	fmt.Println()
	fmt.Println("【Q3】为什么越权要返 404 而不是 403？")
	fmt.Println("  参考答案：")
	fmt.Println("    403 等于告诉攻击者「这个 id 存在，只是你不能看」。")
	fmt.Println("    在多租户系统里，「某id 是否存在」本身就是需要保护的信息——")
	fmt.Println("    攻击者可以用它探测出哪些家庭有数据、甚至有哪些用户在用。")
	fmt.Println("    返 404 让「不存在」和「存在但没权限」在外部观察上完全一致。")
	fmt.Println("    注意边界：3002「权限不足」可以返403，因为它不涉及具体对象 id。")

	fmt.Println()
	fmt.Println("### scripts/s2-check.sh 完整内容（今天任务的产物）")
	fmt.Println("────────────────────────────────────────")
	// 用 io.WriteString 而不是 Print/Println：
	// 脚本正文里含大量 %s 和 \n，Print/Println 会把它当成格式串（vet 会报警）。
	_, _ = io.WriteString(os.Stdout, s2CheckSh)
	fmt.Println("────────────────────────────────────────")

	if fail > 0 {
		os.Exit(1)
	}
}
